      "description": "제주도 한가운데 솟아 있는 한라산은 우리나라에서 가장 높은 산으로, 정상의 높이는 약 1,947미터입니다. 오랜 화산활동이 만들어 낸 산이라 정상에는 백록담이라는 분화구 호수가 있고, 산기슭에는 작은 화산체인 오름이 여럿 퍼져 있습니다. 백록담이라는 이름에는 흰 사슴이 내려와 물을 마셨다는 이야기가 전해집니다. 높이가 달라질수록 기온과 식물도 달라져 아래쪽의 숲에서 정상 부근의 낮은 풀밭까지 다양한 자연을 만날 수 있습니다. 겨울의 눈 덮인 능선과 여름의 푸른 숲은 같은 산이라고 믿기 어려울 만큼 다른 모습을 보여 줍니다. 한라산은 국립공원이자 천연보호구역으로 관리되며, 제주 화산섬과 용암동굴 세계자연유산의 중요한 부분을 이룹니다. 한라산은 높이가 달라질수록 자연환경도 크게 변합니다. 아래에서는 넓은 잎을 가진 나무가 울창한 숲을 이루지만, 위로 올라가면 추위와 강한 바람을 견디는 식물이 나타납니다. 봄철 진달래가 산을 물들이고 가을에는 단풍이 내려앉으며, 겨울 정상에는 바람이 빚은 눈과 얼음의 모양이 펼쳐집니다. 하나의 산에서 여러 계절과 높이별 생태계를 함께 경험할 수 있다는 점이 한라산을 더욱 특별하게 합니다.",
