      "description": "강원도의 설악산은 날카로운 바위봉우리와 깊은 계곡, 울창한 숲이 어우러진 산입니다. 가장 높은 대청봉은 해발 약 1,708미터이며, 주변에 공룡능선과 울산바위처럼 모양이 독특한 암봉이 이어집니다. '설악'이라는 이름에는 눈이 오래 남는 산이라는 뜻이 담겨 있습니다. 봄에는 연둣빛 새잎이 산을 채우고, 여름에는 계곡을 따라 물이 흐르며, 가을에는 단풍이 바위벽과 선명한 대비를 이룹니다. 겨울에는 눈과 얼음이 능선을 하얗게 덮습니다. 국립공원인 설악산은 여러 희귀한 동식물이 살아가는 중요한 자연환경이기도 합니다. 거친 바위와 계절마다 바뀌는 숲의 모습이 설악산이 지닌 가장 큰 매력입니다. 설악산의 공룡능선은 바위봉우리들이 공룡의 등뼈처럼 이어져 보인다는 데서 이름을 얻었습니다. 울산바위는 주변 봉우리와 다른 거대한 바위 덩어리로, 그 기묘한 모습 때문에 여러 옛이야기가 전해집니다. 산에는 작은 암자와 오래된 사찰도 있어 자연풍경 속에 사람들이 쌓아 온 신앙의 역사가 남아 있습니다. 해안에서 가까운 산이면서도 높은 산악지대의 거친 자연을 품고 있다는 사실이 설악산 풍경의 비밀입니다.",
