      "description": "국립중앙박물관은 우리나라의 오랜 역사를 한곳에 모아 놓은 서울 용산의 대표 박물관입니다. 선사시대에 쓰던 도구부터 삼국시대의 불상과 도자기, 조선시대의 그림까지 시대를 건너온 유물들이 이어집니다. 오늘날의 국립중앙박물관은 1945년 광복 직후 출범한 국립박물관을 뿌리로 하며, 2005년 용산에 새 보금자리를 마련했습니다. 오래된 유물에는 유명한 왕의 이름만 남아 있는 것이 아닙니다. 그릇 하나에는 음식을 만들던 사람의 손길이, 장신구에는 당시 사람들이 아름답다고 생각했던 모양이 담겨 있습니다. 서로 다른 시대의 물건을 나란히 만나는 경험은 수백 년 전 사람들도 우리처럼 집에서 살고, 가족을 아끼고, 새로운 것을 만들었다는 사실을 일깨워 줍니다.\n\n국립중앙박물관에는 오랜 세월 한반도에서 살아온 사람들의 흔적이 시대별로 이어집니다. 작은 토기와 돌도끼부터 불상, 금속공예, 서화까지 유물의 재료와 모양이 달라지며 생활과 믿음도 어떻게 변했는지 알려줍니다. 한 점의 유물에는 만든 사람뿐 아니라 그것을 쓰고 지켜 온 수많은 사람의 시간이 담겨 있습니다.",
