      "description": "서울 도심을 가로지르는 청계천은 도시의 긴 역사가 담긴 물길입니다. 조선시대에는 한양의 빗물과 생활하수가 모여 흐르던 하천이었고, 주변에는 사람들이 모여 살며 시장과 다리가 생겨났습니다. 근대에 도시가 빠르게 커지면서 하천 일부가 콘크리트로 덮였고 그 위로 도로와 고가도로가 들어섰습니다. 2000년대 초 복원사업을 거쳐 2005년 물길이 다시 드러나자 청계천은 시민들이 산책하고 쉬는 공간으로 바뀌었습니다. 오늘날의 청계천에는 도시의 다른 곳에서 끌어온 물도 흐릅니다. 옛 돌다리의 흔적과 현대식 보행로가 함께 남아 있어, 한 도시가 자연과 관계를 맺는 방식이 시대에 따라 어떻게 달라지는지 보여 줍니다. 청계천에는 조선시대 사람들의 발길이 오가던 다리의 이름과 흔적도 남아 있습니다. 복원 이후에는 도심에서 물소리와 식물을 접할 수 있게 되었지만, 모든 물길이 원래 자연 그대로 되살아난 것은 아닙니다. 인공적으로 공급되는 물과 새롭게 만든 산책로가 함께 있기 때문입니다. 오래된 하천을 현대 도시에서 어떻게 되살릴 것인가를 보여 주는 사례라는 점에서 청계천은 서울의 과거와 미래를 동시에 품고 있습니다.",
