      "description": "장가계 국가삼림공원은 중국 후난성의 산악지대로, 수많은 가느다란 바위기둥이 숲 위로 솟아 있는 풍경으로 유명합니다. 오랜 침식과 풍화가 사암 지형을 깎아 독특한 기둥 모양을 만들었습니다. 안개가 낮게 깔리면 바위산 꼭대기만 구름 위로 드러나 다른 세계처럼 보입니다. 산책로와 전망대에서는 같은 지형도 보는 높이에 따라 전혀 다르게 펼쳐집니다.\n\n장가계의 뾰족한 기암은 누군가 돌기둥을 세워 놓은 것이 아닙니다. 아주 오랜 시간 동안 비와 바람, 물길이 암석의 약한 부분을 깎으면서 남은 봉우리들이 하늘로 솟은 듯한 풍경을 이루었습니다. 구름과 안개가 계곡 사이를 흐르는 날이면 높은 바위산만 구름 위에 떠 있는 것처럼 보여 더욱 신비롭습니다.",
