      "description": "상하이 타워는 중국 상하이 푸둥의 초고층 빌딩들이 모인 루자쭈이에 솟아 있습니다. 높이 632m에 128층 규모로, 멀리서 보면 건물의 몸체가 하늘을 향해 조금씩 비틀리며 올라가는 듯합니다. 이 특별한 모양은 단순히 멋을 내기 위한 장식만은 아닙니다. 높은 곳에서 강한 바람을 받는 초고층 건물이 바람의 영향을 줄이도록 고민한 설계입니다. 건물에는 여러 층을 하나의 구역으로 묶은 공간들이 있고, 사무실과 상업시설, 전망 공간이 들어서 있습니다. 한 세기 전 황푸강 건너 와이탄에서 서양식 건물들이 상하이의 번영을 드러냈다면, 오늘날 상하이 타워는 도시가 얼마나 높이 자라났는지를 보여 줍니다. 강 양쪽의 전혀 다른 하늘선에는 상하이의 시간이 나란히 서 있습니다.\n\n상하이 타워는 높이만으로 유명한 건물이 아닙니다. 건물이 위로 올라가면서 조금씩 비틀리는 독특한 외형은 강한 바람이 건물에 주는 힘을 줄이도록 계획되었습니다. 주변의 초고층 건물들과 나란히 선 모습은 불과 몇십 년 사이 크게 변한 푸둥 지역의 도시 발전을 상징합니다.",
