      "description": "상하이 와이탄은 황푸강 서쪽 강변을 따라 옛 건축물들이 길게 늘어선 거리입니다. 19세기 중반 이후 상하이가 국제무역의 중심지로 성장하면서 은행과 무역회사들이 이곳에 사무실을 세웠습니다. 그래서 한 거리에서 고전주의, 고딕 양식, 아르데코 등 서로 다른 유럽 건축 양식을 만날 수 있습니다. 강 건너 푸둥에는 상하이 타워와 현대적인 초고층 빌딩들이 솟아 있어, 옛 상하이와 새로운 상하이가 한 장면 안에서 마주 봅니다. 낮에는 건물의 기둥과 장식이 또렷하게 보이고 밤에는 강변 조명이 물 위에 길게 비칩니다. 와이탄은 화려한 산책로일 뿐 아니라 상하이가 국제도시로 성장한 시간을 보여 주는 살아 있는 건축 기록입니다. 와이탄의 옛 건물 중에는 시계를 단 큰 건물과 세밀한 돌기둥으로 장식된 은행 건물들이 있어 한 시대의 상업 중심지가 얼마나 번성했는지 짐작하게 합니다. 황푸강은 수많은 배가 오가며 도시의 물자와 사람을 실어 나르던 길이었습니다. 지금도 강의 양쪽 풍경은 상하이의 시간을 선명하게 대비시킵니다. 한편 이 거리의 아름다움 뒤에는 외국의 영향력이 컸던 역사도 있어, 화려한 건축만으로는 설명할 수 없는 도시의 이야기가 남아 있습니다.",
