      "description": "청두 판다기지는 중국 쓰촨성 청두에 자리한 자이언트판다 보호·연구 시설입니다. 이곳에서는 판다가 건강하게 살아가도록 돌보고, 번식과 행동을 연구하며, 멸종 위기 동물을 보호하는 방법을 알립니다. 연구기지는 1987년 야생에서 구조된 판다 여섯 마리로 시작했습니다. 오늘날 판다가 대나무를 먹거나 나무에 기대 쉬는 모습은 사람들에게 사랑받지만, 판다가 지닌 생태학적 의미는 귀여운 외모보다 훨씬 큽니다. 서식지인 산림이 잘 보존되어야 야생 판다도 살아갈 수 있기 때문입니다. 판다를 보호하려는 노력은 숲을 함께 쓰는 다른 동물과 식물의 삶까지 지키는 일로 이어집니다. 이곳의 이야기는 한 종류의 동물을 아끼는 마음이 자연 전체를 돌보는 일로 확장될 수 있음을 보여 줍니다.\n\n청두 판다기지는 사랑스러운 판다를 보여주는 공간이면서 동시에 멸종위기 동물의 번식과 보호를 연구하는 곳입니다. 판다는 대나무를 주로 먹기 때문에 하루 중 많은 시간을 먹고 쉬는 데 보냅니다. 새끼 판다는 태어났을 때 아주 작고 연약하지만 자라면서 우리가 잘 아는 검고 흰 털을 갖게 됩니다. 귀여운 모습 뒤에는 생명을 지키기 위한 오랜 연구가 이어지고 있습니다.",
