      "description": "도쿄 스카이트리는 일본 도쿄의 스미다구에 세워진 방송·전망탑입니다. 높이 634m에 이르는 날렵한 구조물은 2012년 문을 열었습니다. 높은 건물이 빽빽한 도쿄에서는 전파를 멀리 보내기가 쉽지 않았고, 스카이트리는 새로운 방송 환경을 위한 시설로 계획되었습니다. 탑 아래에는 상업시설과 수족관이 모여 있어 일상의 거리와 거대한 전망탑이 이어집니다. 위쪽 전망 공간에서는 도쿄의 도로와 강, 빌딩들이 작은 모형처럼 펼쳐집니다. 도쿄타워가 전후 일본의 성장기를 떠올리게 한다면, 스카이트리는 디지털 방송과 초고층 도시의 시대를 상징합니다. 하늘을 향한 높이만큼이나 건축과 기술이 함께 발전해 온 도시의 이야기가 담긴 탑입니다.\n\n도쿄 스카이트리가 높이 634미터로 정해진 데에는 재미있는 말놀이도 담겨 있습니다. 일본어로 숫자 6·3·4를 읽는 방식 가운데 하나가 도쿄 일대의 옛 지명인 무사시를 떠올리게 하기 때문입니다. 초고층 건물이 많은 도시에서 전파를 넓게 송출하고, 높은 전망대에서 거대한 수도의 모습을 보여주는 역할을 함께 합니다.",
