      "region": "파리",
      "aliases": [
        "Champs Elysees",
        "Avenue des Champs-Élysées",
        "Champs-Élysées"
      ],
      "description": "프랑스 파리의 샹젤리제 거리는 콩코르드 광장에서 개선문이 있는 샤를 드골 광장까지 이어지는 넓은 거리입니다. 이름은 그리스 신화에서 영웅들의 영혼이 머문다고 전해지는 ‘엘리시온의 들판’에서 유래했습니다. 극장과 카페, 상점이 줄지어 있고, 국가의 중요한 행사가 열릴 때는 거리가 커다란 무대가 됩니다. 프랑스 혁명을 기념하는 국경일에는 군사 행진이 지나가고, 세계적인 자전거 경기 투르 드 프랑스도 이 거리에서 마지막 장면을 맞이합니다. 그러나 처음부터 지금과 같은 화려한 거리였던 것은 아닙니다. 도시가 변화하면서 길의 성격도 계속 달라졌습니다. 샹젤리제는 파리의 일상과 축제, 오래된 신화가 한 줄의 길 위에 겹쳐 있는 장소입니다.\n\n샹젤리제라는 이름은 고대 그리스 신화에서 행복한 영혼이 머무는 들판을 뜻하는 말에서 왔습니다. 지금은 콩코르드 광장에서 개선문으로 이어지는 큰 길을 따라 극장과 상점, 카페가 늘어서 있습니다. 프랑스의 국가적인 기념행사와 자전거 경기의 중요한 장면도 이 거리에서 펼쳐져, 단순한 쇼핑 거리를 넘어 파리의 상징적인 무대가 되었습니다.",
