      "description": "니스 영국인 산책로는 프랑스 남부 니스의 지중해 해안을 따라 길게 이어진 산책길입니다. 이름에 ‘영국인’이 들어간 까닭은 19세기 이 지역에서 겨울을 보내던 영국인 방문객들과 관련이 있습니다. 약 7km에 걸친 길의 한쪽에는 푸른 바다가 펼쳐지고 다른 쪽에는 니스의 거리와 건물들이 이어집니다. 지중해의 햇살과 바닷바람 덕분에 이곳은 오래전부터 휴양도시의 상징이 되었습니다. 해안에서는 자갈이 많은 해변이 독특한 소리를 내고, 바다의 색은 날씨와 계절에 따라 달라집니다. 아름다운 풍경 뒤에는 먼 나라의 사람들이 겨울을 보내러 찾아오며 도시의 문화와 거리 모습까지 바꾸어 놓았던 이야기가 숨어 있습니다.\n\n니스의 영국인 산책로는 프랑스 남부 지중해를 따라 길게 뻗은 해안 산책길입니다. 19세기 무렵 이곳에서 겨울을 보내던 영국인 방문객들과 관련해 지금의 이름이 붙었습니다. 푸른 바다를 따라 늘어선 야자수와 호텔, 곡선을 그리는 해안선은 니스의 오랜 휴양도시 역사를 보여줍니다.",
