      "description": "교토의 금각사는 연못 가장자리에 서 있는 금빛 누각으로 유명한 불교 사찰입니다. 공식 이름은 로쿠온지이며, 우리가 금각사라고 부르는 건물은 위쪽 두 층을 금박으로 장식한 사리전입니다. 맑은 날에는 금빛 벽과 지붕이 연못 수면에 비쳐 건물이 둘로 보이는 듯합니다. 지금 보이는 누각이 처음 지어진 그대로 남은 것은 아닙니다. 1950년 화재로 소실되었고, 1955년 다시 세워졌습니다. 따라서 금각사는 옛 건축의 아름다움뿐 아니라 사라진 문화유산을 어떻게 되살리고 지킬 것인가라는 이야기도 품고 있습니다. 화려한 금빛 누각과 차분한 정원이 대비되는 이곳은 일본의 전통미와 역사의 굴곡을 함께 전합니다.",
