      "description": "로마의 판테온은 약 2천 년 전에 세워진 고대 로마 건축의 놀라운 성과입니다. 지금 보이는 건물은 하드리아누스 황제 시대에 재건된 것으로, 앞쪽에는 거대한 기둥이 늘어서 있고 안쪽에는 둥근 천장이 펼쳐집니다. 가장 놀라운 부분은 지름 약 43미터에 이르는 콘크리트 돔입니다. 돔 한가운데에는 '오쿨루스'라는 둥근 구멍이 있어 햇빛이 실내로 들어옵니다. 비가 오는 날에는 빗방울도 그 구멍을 지나 바닥으로 떨어집니다. 로마인들은 철근이 없는 콘크리트로 이처럼 넓은 돔을 완성했고, 그 구조는 훗날 수많은 건축가에게 영감을 주었습니다. 판테온은 고대 신전으로 시작했지만 7세기부터 교회로 사용되면서 오랜 세월 모습을 지킬 수 있었습니다. 하나의 건물 안에 로마의 기술과 종교의 변화가 함께 남아 있습니다. 햇살이 오쿨루스를 지나 원형 벽을 따라 이동하는 모습은 건물 안에 거대한 시계가 있는 듯한 인상을 줍니다. 돔은 위로 올라갈수록 비교적 가벼운 재료를 사용해 무게를 줄이도록 만들어졌습니다. 판테온 앞 기둥에는 고대 로마의 정치가 아그리파의 이름이 새겨져 있어, 오늘의 건물보다 오래된 신전의 기억까지 이어 줍니다. 천장과 바닥의 비례가 정교하게 맞아떨어지는 공간은 지금도 건축가들이 연구하는 대상입니다.",
