      "description": "서울 종묘는 조선 왕과 왕비의 신주를 모시고 제사를 지내던 특별한 공간입니다. 조선이 한양을 수도로 정한 뒤 1395년 세워졌으며, 전쟁으로 불타 없어진 뒤 다시 지어졌습니다. 궁궐이 왕과 가족이 살며 나라를 다스리던 곳이라면 종묘는 조상에 대한 예와 기억을 이어 가는 장소였습니다. 길게 뻗은 정전의 모습은 화려한 장식보다 엄숙한 분위기를 중요하게 생각한 건축의 특징을 보여 줍니다. 종묘에서는 제사에 쓰이는 음악과 춤도 함께 이어져 왔습니다. 건물만 남아 있는 유적이 아니라 의식과 음악, 사람들이 지켜 온 약속이 함께 전해진다는 점이 특별합니다. 종묘는 1995년 유네스코 세계유산에 등재되어 그 가치를 인정받았습니다.",
