      "description": "수원 화성은 조선 정조 시대에 수원에 건설한 성곽입니다. 정조는 아버지 사도세자를 기리는 마음과 새로운 도시를 키우려는 뜻을 품고 성을 세우도록 했습니다. 성벽의 길이는 약 5.7km이며 성문, 포루, 공심돈 같은 여러 방어시설이 둘러서 있습니다. 특히 벽돌과 돌을 알맞게 사용하고 지형에 맞춘 구조를 만드는 등 당시의 새로운 기술이 적용되었습니다. 건설 과정에는 도르래와 같은 기구를 활용해 큰 돌과 자재를 옮기는 노력도 있었습니다. 수원 화성은 단순히 적의 공격을 막는 시설만이 아니라 계획도시의 중심이었습니다. 1997년 유네스코 세계유산에 오른 이 성곽에는 부모를 향한 왕의 마음과 실용적인 건축기술을 발전시키려던 시대의 꿈이 함께 남아 있습니다.",
