      "description": "제주 중문·대포해안의 주상절리대에는 바닷가를 따라 육각형 기둥처럼 갈라진 검은 바위들이 늘어서 있습니다. 이 바위는 사람들이 하나씩 쌓아 올린 것이 아닙니다. 뜨거운 용암이 흘러나와 식고 굳는 과정에서 부피가 줄어들면서 규칙적인 틈이 생긴 것입니다. 이렇게 형성된 기둥 모양의 암석을 주상절리라고 부릅니다. 절벽의 기둥들은 나란히 서 있기도 하고 높낮이가 달라 계단처럼 보이기도 합니다. 파도가 거세게 밀려오는 날에는 하얀 물보라가 검은 바위와 부딪쳐 장관을 이룹니다. 이곳은 제주도가 화산활동으로 만들어진 섬임을 보여 주는 자연의 기록입니다. 오랜 시간이 지나도 남아 있는 기둥의 모양은 용암이 식던 순간을 오늘날까지 전해 줍니다. 기둥들은 얼핏 모두 같은 육각형으로 보이지만 실제로는 네모나 다섯모 모양도 섞여 있습니다. 용암이 식는 속도와 갈라지는 방향에 따라 모양과 굵기가 조금씩 달라졌기 때문입니다. 바닷물이 들어왔다 나갔다 하는 자리에서는 거센 파도가 계속 바위를 때립니다. 제주도에서 '검은 돌'이라고 부르는 현무암에 이처럼 질서 정연한 무늬가 생긴 까닭을 알면, 해안 절벽 전체가 커다란 지구과학 책처럼 보입니다.",
