      "description": "교토의 은각사는 이름과 달리 은빛으로 덮여 있지 않은 절입니다. 무로마치 막부의 쇼군 아시카가 요시마사가 15세기 후반에 은퇴 후 머물 별장을 마련한 데서 시작되었으며, 그의 사후 불교 사찰이 되었습니다. 정식 이름은 지쇼지이지만, 금각사와 짝을 이루는 이름인 은각사로 더 널리 알려져 있습니다. 나무로 된 관음전은 화려한 장식보다 차분하고 절제된 분위기를 전합니다. 주변에는 하얀 모래를 정교하게 다듬어 만든 정원과 연못, 이끼가 덮인 숲길이 이어집니다. 모래를 높이 쌓아 만든 원뿔 모양의 향월대도 독특한 볼거리입니다. 은각사에서 발전한 동산문화는 정원과 다도, 건축의 아름다움에 깊은 영향을 미쳤습니다. 금빛 찬란함 대신 고요한 풍경으로 기억되는 장소입니다.",
