      "description": "교토의 니조성은 일본의 에도 막부를 열었던 도쿠가와 이에야스가 17세기 초에 지은 성입니다. 이곳은 높은 천수각보다 화려한 궁전 건물과 정원, 그리고 정치사의 중요한 장면으로 유명합니다. 니노마루 궁전의 복도는 사람이 걸으면 바닥에서 새가 지저귀는 것 같은 소리가 나 '꾀꼬리 마루'라고 불립니다. 발걸음에 따라 마룻바닥의 부속 구조가 마찰하며 소리를 내는 것입니다. 궁전 안의 벽과 미닫이문에는 호랑이, 소나무, 꽃 등을 그린 장식화가 남아 있어 당시 권력자의 위엄을 전합니다. 1867년에는 마지막 쇼군 도쿠가와 요시노부가 이곳에서 정권을 천황에게 돌려주겠다는 뜻을 밝힌 역사적 사건이 있었습니다. 니조성은 교토의 다른 문화유산들과 함께 유네스코 세계유산에 등재되어 있습니다.",
