      "description": "교토 남쪽 우지의 뵤도인은 원래 귀족의 별장이었지만 11세기에 불교 사찰로 바뀌었습니다. 가장 유명한 건물은 연못 한가운데 세워진 봉황당입니다. 지붕 위에는 봉황 장식이 놓여 있고, 중앙 건물의 양옆 날개가 길게 뻗어 있어 새가 날개를 펼친 듯한 모습입니다. 내부에는 아미타여래상이 모셔져 있으며, 극락정토를 표현하려 했던 당시 사람들의 신앙과 예술을 보여줍니다. 봉황당은 일본의 10엔 동전에도 등장할 만큼 널리 알려져 있습니다. 건물 앞의 연못에는 봉황당의 모습이 비쳐 물 위에 또 하나의 궁전이 떠 있는 듯합니다. 뵤도인은 1994년 '고도 교토의 문화재' 가운데 하나로 유네스코 세계유산에 등재되었습니다. 천 년 가까이 이어진 아름다운 건축과 신앙의 만남을 보여줍니다.",
