      "description": "차이나타운(Chinatown) 또는 당인가, 중화가(中華街), 중국인가(中國人街)는 중국 한족의 세력이 가장 약화되었던 송대부터 시작되어 청나라 말기에 본격적으로 전 세계에 퍼진 한족이 이주한 나라에서 모여 살며 형성한 지역이나 그 사회입니다. 지금은 다음으로 세계적인 영향력을 행사하는 중국 상인들을 중심으로 세계 각국에 차이나타운이 형성되어 있습니다. 동남아시아 지역과 아메리카 지역의 중국인들은 대부분 광둥성을 중심으로 살던 사람들이 많았고 중국의 가장 하층계급인 쿨리라 불리는 사람들이 주를 이루었었다. 한국은 산둥성을 중심으로 살던 중국인이 이주하여 관화를 쓰는 사람들이 많지만 그 외 세계의 다른 지역은 광동어 등을 쓰는 사람들이 주를 이룬다.",
