      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "오르세 미술관은 프랑스 파리의 센강 좌안에 있는 박물관입니다. 1898년부터 1900년까지 건설된 보자르 양식의 옛 오르세역 건물에 자리하고 있습니다. 이 미술관은 주로 1848년부터 1914년까지의 프랑스 미술 작품(프랑스에서 활동했던 외국 예술가들의 작품 포함)을 소장하고 있으며, 회화, 조각, 가구, 사진 등을 전시하고 있습니다. 베르트 모리조, 클로드 모네, 에두아르 마네, 에드가 드가, 오귀스트 르누아르, 폴 세잔, 조르주 쇠라, 알프레드 시슬레, 폴 고갱, 빈센트 반 고흐 등의 화가들의 인상주의와 후기인상주의 걸작을 세계에서 가장 많이 소장하고 있습니다. 이 작품들 중 상당수는 1986년 미술관 개관 이전에 죄드폼 국립미술관에 소장되어 있었던 것을 이관받은 것입니다.",
