      "description": "오페라 가르니에(Opéra Garnier) 또는 가르니에 궁(Palais Garnier)은 프랑스 파리 9구 오페라 광장 북쪽 끝에 위치한 2200석을 수용하는 오페라 극장입니다. 파리 오페라 극장(Opéra de Paris, Paris Opéra)으로도 알려져 있습니다. 샤를 가르니에가 신바로크 양식으로 설계한 건물로 그 당시 건축학적 걸작 중 하나로 평가된다. 1875년 칙령하에 이 오페라 극장은 공식적으로 '음악 국립 아카데미 - 오페라 극장'으로 명명되었습니다. 이 이름은 1978년까지 유지되었으나, '파리 국립 오페라 극장'으로 개명되었습니다. 1989년 바스티유 오페라 극장의 완공으로, 오페라단이 대표 극장으로 바스티유 오페라를 선택한 뒤로는 가르니에 궁으로 다시 개명되었습니다.",
