      "description": "프랑스 루아르강 유역의 슈농소성은 강 위로 길게 뻗은 우아한 건축물로 유명합니다. 셰르강을 가로지르는 아치형 다리 위에 회랑을 올려 강물에 떠 있는 궁전처럼 보입니다. 16세기에는 앙리 2세의 연인이었던 디안 드 푸아티에가 성을 관리하며 정원을 가꾸었고, 왕이 사망한 뒤에는 왕비 카트린 드 메디시스가 성을 차지해 건물과 정원을 발전시켰습니다. 서로 다른 두 여성이 이 성의 역사에 큰 흔적을 남겼기 때문에 '여인들의 성'이라는 별칭으로도 알려져 있습니다. 제1차 세계대전 때에는 일부 공간이 부상병을 위한 병원으로 사용되었습니다. 전쟁과 왕실의 이야기를 모두 품은 이 성은 강 위의 회랑과 정원이 어우러져 특별한 풍경을 만듭니다.",
