      "aliases": [],
      "description": "수도교(水道橋) 또는 수로교(水路橋), 영어로 애퀴덕트(aqueduct)는 골짜기나 협곡과 같은 단절된 구간을 가로질러 수로를 연결하기 위해 건설된 교량입니다. 수도교라는 용어는 교량뿐만 아니라 전체 수로를 지칭하기도 합니다. 거대한 운하교는 배나 선박의 이동 경로로 사용된다. 수도교는 양 끝의 수로와 같은 높이로 횡단 구간을 연결해야 합니다. 애퀴덕트라는 단어는 라틴어 aqua(\"물\")와 ducere(\"이끌다\")에서 유래했으며, 따라서 \"물을 이끄는 것\"을 의미합니다. 수도교의 현대적 형태는 파이프라인 교량입니다. 이는 터널, 지표면 수로 및 운하망, 덮개가 있는 점토관 또는 기념비적인 교량의 형태를 띨 수 있습니다.",
