      "aliases": [],
      "description": "웨스트민스터궁(Palace of Westminster)은 영국 런던에 소재한 국회의사당(Houses of Parliament)입니다. 영국의 상원과 하원의회장이 모두 이 건물에 자리하고 있습니다. 런던 자치구의 시티 오브 웨스트민스터의 템스강 북쪽에 있으며, 정부 청사들이 있는 화이트홀과 가깝다. 기존 건물을 포함하여 약 1,100개의 방과 100여개의 계단 그리고 4.8km의 복도가 있습니다. 건물 대부분은 19세기까지 거슬러 올라가지만, 초기의 원형 건물 가운데 살아남은 요소는 오늘날에는 유해의 정장(正裝) 안치와 같은 중요한 국가행사를 치를 때 사용하는 웨스트민스터 홀과 보석 탑 등입니다. 웨스트민스터 궁전의 빅토리아 탑에는 200만 건이 넘는 서류가 보관되어 있으며 궁전의 북쪽 끝에는 빅벤이라 불리는 대형 탑시계가 있습니다.",
