      "aliases": [],
      "description": "버킹엄 궁전(Buckingham Palace)은 영국 런던 시티오브웨스트민스터에 있는 궁전입니다. 1703년 버킹엄 공작 존 셰필드의 저택으로 세워진 것을 1761년에 조지 3세에게 양도되어 지금의 모습으로 증개축을 한 후 사저로 이용되다가 1837년 빅토리아 여왕의 즉위식 때에 궁전으로 격상되어 이후 역대 군주들이 상주하였습니다. 영국 군주의 공식적인 사무실 및 주거지로 쓰이고 있기 때문에 현재 영국 왕실의 대명사이기도 하다. 2만m²의 호수를 포함해 약 17만m²에 이르는 대정원, 그리고 무도회장, 음악당, 미술관, 접견실과 도서관 등이 들어서있습니다. 버킹엄 궁의 방수는 알현실 19개, 손님용 침실 52개, 스태프용 침실 188개, 사무실 92개, 욕실 78개를 포함하여 총 775개입니다.",
