      "category": "modern",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "타워 브리지(Tower Bridge)는 영국 런던에 위치한 1등급 등록문화재로, 복합적인 구조의 다리입니다. 이 다리는 도개교, 현수교, 1960년까지는 캔틸레버교의 특성을 모두 갖추고 있었다. 1886년부터 1894년 사이에 건설되었으며, 호레이스 존스가 설계하고 존 울프 배리가 헨리 마크 브루넬의 도움을 받아 공학적 설계를 담당했습니다. 다리는 런던탑 근처에서 템스강을 가로지르며, 1282년에 설립된 자선 단체인 시티 브리지 재단이 소유하고 관리하는 런던의 다섯 개 다리 중 하나입니다. 타워 브리지는 런던 브리지 동쪽에 거주하는 런던 인구의 39%를 연결하기 위해 건설되었습니다. 이는 \"한쪽의 맨체스터와 다른 쪽의 리버풀\"의 인구와 맞먹는 규모였습니다. 동시에 런던탑과 런던교 사이의 풀오브런던으로 선박이 접근할 수 있도록 설계되었습니다.",
