      "region": "",
      "aliases": [],
      "description": "런던탑은 영국 잉글랜드 센트럴런던의 템스강 북안에 있는 유서깊은 성이자 궁전입니다. 정식 명칭은 국왕 폐하의 궁전이자 요새인 런던탑입니다. 행정 구역상으로는 타워햄리츠구에 속해 있으며 서쪽은 타워힐 공원을 사이에 두고 시티오브런던과 마주하고 있습니다. 노르만의 잉글랜드 정복 이후인 1066년에 세워진 요새를 기반으로 건축되었습니다. 런던탑의 명칭은 1078년 정복왕 윌리엄이 잉글랜드에 새로운 지배자가 들어섰음을 상징하는 건물로서 세운 화이트 타워에서 유래되었습니다. 런던탑은 1100년(더럼 주교 래널프 플램바드)부터 1952년(크레이 형제)까지 종종 감옥으로 쓰였지만, 그것이 주된 기능은 아니었다. 15세기 후반에는 장미 전쟁의 와중에 에드워드 5세와 요크 공작 슈루즈베리의 리처드 형제가 런던탑에 갇혔다가 행방이 묘연해진 런던탑의 두 왕자 사건이 발생하기도 하였습니다.",
