      "description": "대영박물관은 영국 런던에 있는 대규모 박물관으로, 세계 여러 문명의 유물을 전시합니다. 고대 이집트의 로제타석과 그리스·로마 유물, 아시아의 공예품 등 서로 다른 지역의 문화자료를 만날 수 있습니다. 여러 유물의 수집과 반출을 둘러싼 논쟁도 존재해 문화재의 소유와 보존에 대해 생각하게 합니다. 거대한 중앙 홀은 옛 박물관 건물과 현대적인 유리 지붕이 결합된 공간입니다.",
