      "region": "",
      "aliases": [],
      "description": "런던 아이는 영국 런던의 템스강 사우스뱅크에 있는 캔틸레버식 대관람차입니다. 2000년 3월에 개관하였으며, 원래 이름은 밀레니엄 휠입니다. 런던에서 가장 인기 있는 유료 관광 명소로 매년 300만 명 이상이 방문합니다. 런던 아이는 높이 135 m로 회전하는 휠의 지름은 120 m입니다. 2000년 개관 당시에는 세계에서 가장 높은 대관람차이었다. 현재는 2022년 개관한 솔른체 모스코비(높이 140 m), 2006년 세워진 난창의 별(165 m), 2008년 세워진 싱가포르 플라이어(167 m), 2014년 라스베거스에 세워진 하이롤러(250 m) 등 런던 아이 보다 큰 대관람차가 여럿 생겼다. 다만 외팔보 방식의 관람차 가운데는 여전히 세계에서 가장 높다. 가장 높은 곳에서 런던의 전망을 바라볼 수 있는 장소였지만 2013년 초 마천루인 더 샤드의 72층에 245 m 높이에서 런던을 바라볼 수 있는 전망대가 세워져 이마저도 2위로 밀려났다.",
