      "description": "Paul’s Cathedral)은 시티 오브 런던의 러드게이트 힐(Ludgate Hill)에 있는 높이 111m의 성공회 성당으로, 런던 주교좌가 자리 잡고 있습니다. 세인트 폴 대성당은 사도 바울로에게 봉헌된 성당으로, 기원후 604년에 이 곳에 지어져 있던 성당을 그 원형으로 하여 세워졌다. 원래 있었던 세인트폴 대성당은 1666년 런던 대화재 때 불타 버렸으며, 1675년에 크리스토퍼 렌 경의 감독 하에 영국 바로크 양식으로 다시 짓기 시작하여 35년 만에 완공됐다. 불타기 전 옛 세인트 폴 대성당은 런던 시가지의 중심지에 자리하고 있었다. 세인트 폴 대성당은 런던에서 가장 유명한 랜드마크들 중 하나로, 특히 멀리서도 잘 보이는 대성당의 돔은 약 300여 년이 넘는 시간 동안 런던의 스카이라인 속에 자리하고 있었다.",
