      "description": "트라팔가 광장(Trafalgar Square)은 영국 런던 코번트 가든에 있는 광장으로 1805년 트라팔가르 해전을 기념하여 만든 곳입니다. 처음엔 윌리엄 4세 광장이란 이름으로 불렸으나, 건축가였던 조지 리드웰 테일러(George Ledwell Taylor)의 제안으로 인해 트라팔가 광장이 되었습니다. 이 광장은 에드워드 1세의 시대에는 왕가의 정원이었다. 1820년대 조지 4세가 건축가 존 내슈에게 이 지역의 재개발을 의뢰하면서 지금의 형태가 된 것은 1845년에 이르러서였습니다. 내셔널 갤러리 바깥으로 나오면 거리의 행위 예술가들을 많이 만나볼 수 있습니다. 대개 막대기 하나를 짚고 서 있는 마술을 선보여 눈길을 끌며, 런더너들에게 버스킹 하면 생각나는 곳으로 꼽힐 만큼 늦은 저녁까지 버스커들로 붐빈다.",
