      "description": "에든버러성은 스코틀랜드 에든버러에 있는 역사적인 성입니다. 성은 캐슬 록 (에든버러)에 서 있는데, 이곳은 적어도 철기 시대부터 인간이 거주해 왔다. 11세기 말 콜룸 3세 통치 이후로 이 바위에는 왕궁이 있었으며, 성은 1633년까지 왕실 거주지로 사용되었습니다. 15세기부터 성의 주거 역할은 줄어들었고, 17세기에는 주로 군사 주둔지로 사용되었습니다. 19세기 초부터 스코틀랜드 국가 유산의 일부로서 그 중요성이 점점 더 인정받았으며, 지난 한 세기 반 동안 다양한 복원 프로그램이 진행되었습니다. 에든버러성은 스코틀랜드 역사에서 중요한 역할을 했으며, 왕실 거주지, 병기창, 재무부, 국가 기록 보관소, 스코틀랜드 조폐국, 교도소, 군사 요새, 그리고 스코틀랜드 명예 훈장인 스코틀랜드 왕실 휘장의 본거지로 다양하게 사용되었습니다.",
      "photos": [],
      "status": "초안",
      "verified": false,
