      "description": "브란덴부르크 문은 18세기에 베를린에 지어진 초기 고전주의 양식 개선문입니다. 프로이센 왕국의 제4대 국왕인 프리드리히 빌헬름 2세가 바타비아 공화국과의 전쟁 이후 피폐해진 베를린을 복구할 때 함께 1788년부터 1791년까지 지었고 건축가는 칼 고트하르트 랑한스(de)이며 아테네의 아크로폴리스를 참고했습니다. 브란덴부르크 문은 서부 베를린 중심에 있습니다. 브란덴부르크 문에서는 역사적인 사건이 많이 일어났으며 지금은 단순히 독일만의 상징이 아니라 유럽 전체의 통합과 번영을 상징하는 건축물로 떠오르고 있습니다.",
