      "name": "베를린 장벽 이스트사이드 갤러리",
      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "베를린 장벽은 동독이 1961년 8월 12일 밤에서 13일 새벽 사이에 베를린 한가운데 세운 장벽입니다. 처음에는 철조망 형태로 1961년 8월과 9월에 걸쳐 설치되었고, 이후 같은 해 10월부터는 구간에 따라 콘크리트나 벽돌로 된 장벽으로 대체되었습니다. 장벽의 목적은 서독으로 동독 주민들이 계속 탈출하는 것을 막기 위한 것이었다. 서독인들에게는 \"수치의 장벽\",동독 정부에 의해 공식적으로는 \"반파시스트 방벽\"이라고도 불렸다. 장벽은 1945년 7월부터 연합국과 소련이 정한 베를린 분할 경계선을 따라 설치되었으며, 소련 구역 경계선에서 몇 미터 정도 안쪽인 동독령에 설치되었습니다. 따라서 서베를린을 침범하지 않았기 때문에, 국제법적으로는 동독 정부가 자국 영토 내에서 조치한 것으로 간주되어 불법으로 볼 수 없었다.",
