      "description": "호엔슈방가우성은 바이에른 왕국의 왕이자 노이슈반슈타인성을 건립한 루트비히 2세의 아버지인 막시밀리안 2세가 19세기 초엽에 개조를 거쳐 건축한 네오고딕 건축 양식의 성입니다. 독일의 행정 구역상으로는 바이에른주 오스트알고이군 호엔슈방가우에 위치합니다. 1832년부터 1836년 사이에 걸쳐 낡은 슈반슈타인성(Schwanstein)을 재건축한 성입니다. 바이에른 왕가의 황태자 막시밀리안이 이 오래된 성을 신고딕 양식으로 재건하였습니다.",
