      "aliases": [],
      "description": "님펜부르크 궁전은 독일의 바이에른주의 주도 뮌헨에 위치하고 있는, 옛 바이에른 왕국의 통치자였던 비텔스바흐 가문의 여름 별궁입니다. 이름은 님프, 즉 그리스 신화에 나오는 \"요정\"에서 유래하였는데, 궁전 내부의 \"요정들을 거느린 여신의 그림\"에서 모티브를 얻었다. 바이에른의 선제후 페르디난트 마리아가 그의 아들 막시밀리안 2세 에마누엘(1662~1726)의 탄생을 기념하여 짓도록 한 건물로 처음에 지어질 때는 궁전이 아닌 이탈리아 식의 저택이었다. 18세기 초에 막시밀리안 2세 에마누엘은 지금 궁전의 중앙에 해당되는 5층 저택 주변에 네 개의 파빌리온(pavilion)을 더 짓고, 여러 개의 아케이드(arcade)로 이들을 중앙의 저택과 연결시켰다. 본궁인 레지덴츠 궁전과 함께 비텔스바흐 왕가의 대표적인 궁전입니다.",
