      "description": "쾰른 대성당(독일어: Kölner Dom, 정식 명칭: Hohe Domkirche St. Peter)은 독일 쾰른에 있는 로마 가톨릭교회의 성당입니다. 쾰른 대교구의 주교좌 성당이라 쾰른 주교좌 성당이라고도 불린다. 현재 쾰른 대교구의 교구장은 라이너 마리아 뵐키 추기경입니다. 이 성당은 독일에서 가장 잘 알려진 건축물로, 성 바실리 대성당에 이어, 1996년 유네스코 세계유산으로 등재되었습니다. 유네스코에서는 쾰른 대성당을 일컬어 “인류의 창조적 재능을 보여주는 드문 작품”이라고 묘사하였습니다. 매일 2만여 명의 관광객이 이 성당을 찾는다. 쾰른 대성당은 높이 157.38미터로, 울름 대성당에 이어 유럽에서 두 번째, 세계에서는 세 번째로 높은 로마네스크·고딕 양식 성당입니다.",
