      "description": "라인강은 유럽의 강으로 길이는 약 1,230 km입니다. 여러 언어에서 라인강이란 이름은 켈트어의 \"레노스(Renos: 흐르는 것)\"에서 유래했습니다. 원시인도유럽어(PIE) 어근인 \"라이에(reie: 움직이다·흐르다·달리다)\"에서 왔으며 영어의 \"run\"이란 단어도 역시 여기서 유래했습니다. 라인강은 네덜란드와의 국경에서 이름이 바뀌기 때문에 북해로 흘러 들어가지 않는다고도 할 수 있는데, 관례적으로 그 이름이 바뀐 부분까지를 라인강에 포함시킨다. 도나우강과 함께 로마 제국의 북쪽 경계였으며, 그때부터 물자를 내륙 깊이 이동하는 수로로 이용되었습니다. 그러나 4세기 경에 라인강이 언 틈을 타 게르만족이 서로마를 정벌하였습니다.",
