      "aliases": [],
      "description": "포츠담은 독일 동부 하펠강가에 있는 도시로 브란덴부르크주의 주도입니다. 문헌에는 993년에 처음 등장하였으나, 17세기 이전까지는 인구가 적어 발전이 미미한 마을이었다. 1660년 브란덴부르크 선제후 프리드리히 빌헬름의 수렵장으로 지정되었고, 이후 호엔촐레른 왕가의 거점으로 발전하였습니다. 1685년 포츠담 칙령으로 종교의 자유가 보장되어, 네덜란드와 프랑스의 위그노들이 이주하였으며, 18세기 프리드리히 대왕 때 이곳에 상수시 궁전과 같은 수많은 별궁을 세우는 등 도시가 크게 발전하였습니다. 제2차 세계 대전 당시 연합군에게 공습받은 이웃 도시 베를린과 달리 그리 심하게 파괴되지 않아 어느 정도는 옛 모습을 유지하고 있습니다. 제2차 세계 대전 종전 후 체칠리엔호프 궁전에서 포츠담 회담이 개최되었으며, 이후 동독 정권이 수립되면서 동독 치하의 도시가 되었으나 통일 이후 다시 브란덴부르크주의 주도가 되면서, 도시의 초기 외관을 복원하기 위한 다양한 노력을 시도하고 있습니다.",
