      "description": "쉴트호른(Schilthorn)은 스위스 베른주 베르너 오버란트 지역에 있는 해발 2,970m의 산입니다. 산 정상에서 융프라우 삼산( 아이거, 묀히, 융프라우)을 비롯해 200개가 넘는 봉우리들의 큰 파노라마가 펼쳐진다. 게다가 멀리 독일의 검은 숲(슈바르츠발트)이나 프랑스의 보주산맥까지 바라볼 수 있습니다. 산 정상에는 회전 레스토랑 ‘피츠글로리아’가 있습니다. 이 레스토랑은, 액션 영화 007 시리즈의 제6작, 「007 여왕폐하 대작전」의 로케이션 장소가 되었습니다. 건물 자체가 태양광 발전의 힘으로 천천히 회전하기 때문에 자리에 앉은 채 360°의 경관을 즐길 수 있습니다. 1967년에 산 정상까지 케이블카가 개통되었습니다. 산 정상은 매년 1월에 개최되는 세계 최대급의 아마추어 스키 레이스, ‘국제 인페르노 레이스’의 출발지가 되고 있습니다.",
