      "description": "알레치 빙하(Aletsch Glacier) 또는 알레치 글레처(Aletschgletscher)는 스위스 발레주에 있는 알프스산맥 최대의 빙하입니다. 유라시아 대륙의 서쪽 절반에서도 최대로 손꼽힌다. 스위스 발레주의 동부 베른 알프스에 위치하며 길이는 약 23km(2014년), 부피는 약 15.4km3(2011년), 면적은 약 81.7km2(2011년)입니다. 북쪽은 융프라우에, 남쪽은 마사강의 협곡군을 경유하여 론강에, 동쪽은 메르옐렌제 호수(Märjelensee)에, 서쪽은 알레치호른에 각각 둘러싸여 있습니다. 다른 빙하를 포함한 전체 지역은 2001년 유네스코 세계문화유산으로 지정된 융프라우-알레치 보호구역의 일부입니다.",
      "photos": [],
      "status": "초안",
      "verified": false,
      "source": "Stage 1.4 CONTENT FIRST editorial draft",
