      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "리기산는 스위스 중부에 위치한 산으로 높이는 1,798m입니다. 루체른호와 추크호에 둘러싸여 있으며 루체른주와 슈비츠주 사이에 걸쳐 있습니다. 여름에는 하이킹, 겨울에는 스키와 썰매를 즐기려는 사람들이 이 곳을 찾는다. 흔히 “산의 여왕”이라는 별칭으로 부르기도 합니다. 1871년 5월 21일 유럽 최초의 산악 열차가 개통된 곳입니다. 아트-골다우역과 피츠나우역을 연결하는 랙 철도(리기 철도에서 운영함), 베기스에서 리기-칼트바트를 연결하는 곤돌라 리프트, 크레벨역에서 리기-샤이덱역을 연결하는 케이블카가 운행된다.",
