      "description": "취리히는 스위스에서 가장 큰 도시이자 취리히주의 주도이며, 스위스의 중간 지역에 취리히호의 북쪽 끝에 위치해 있습니다. 2020년 1월 기준으로 지방 자치 단체의 인구는 434,335명, 도시 지역(집적)은 131만 5000명(2009), 취리히 대도시 지역은 183만 명(2011년)입니다. 취리히는 철도, 도로 및 항공 교통의 중심지입니다. 취리히 공항과 취리히 중앙역은 모두 이 나라에서 가장 크고 가장 분주하다. 2,000년 이상 동안 영구적으로 정착한 취리히는 기원전 15년에 투리쿰이라고 불리는 로마인에 의해 건설되었습니다. 그러나 초기 정착지는 6,400년 이상으로 거슬러 올라가는 것으로 밝혀졌다. (이것은 해당 지역에 인간이 존재했음을 나타내는 것일 뿐 그렇게 이른 도시의 존재는 아님) 중세 시대에 취리히는 제국의 즉각적이고, 독립적이고, 특권적인 지위를 얻었고, 1519년에는 훌드리히 츠빙글리의 지도 아래 유럽에서 개신교 종교 개혁의 주요 중심지가 되었습니다.",
