      "description": "타롱가 동물원(Taronga Zoo)은 오스트레일리아 뉴사우스웨일스주 시드니 교외의 모스먼, 포트잭슨만 기슭에 있는 국영 동물원입니다. 개장 시간은 현지 시각 기준 오전 9시 30분부터 오후 4시 30분까지입니다. 동물원 이름인 '타롱가'는 오스트레일리아 원주민의 언어로 \"아름다운 경치\"라는 뜻입니다. 타롱가 동물원은 1916년 10월 7일 공식적으로 개장했습니다. 타롱가 동물원 시드니가 더보에 있는 자매 동물원인 타롱가 서부평원동물원과 함께 타롱가 보존 협회란 이름으로 뉴사우스웨일스주 동물원 관리위원회 산하에서 동물원을 관리하고 있습니다. 타롱가 동물원은 28 헥타르 규모로 약 150종 2,000마리 이상을 서식하고 있으며 여러 동물원 구역으로 나눠져 있습니다. 내부에는 동물원 상점, 카페, 안내센터도 있습니다.",
