      "description": "멜버른) 또는 멜번은 오스트레일리아의 도시로, 빅토리아주의 주도입니다. 오스트레일리아에서 시드니 다음으로 큰 도시입니다. 통칭 멜버른이라고 하면 멜버른 시(City of Melbourne) 포함 주변 대도시권 9,900 km2 (3,800 mi²)를 가리킨다. 멜버른의 대도시권은 포트 필립으로부터 단데농 산맥(Dandenong Ranges)과 마세돈 산맥(Macedon Ranges), 그리고 모닝턴 반도(Mornington Peninsula)와 야라 밸리(Yarra Valley)까지 뻗어있습니다. 멜버른은 총 79개의 소도시로 구성되어 있습니다. 2016년 영국 경제전문지 이코노미스트 분석기관 인텔리전트 유닛(EIU)의 ‘살기 좋은 도시’에 6년 연속 1위를 차지한 도시이기도 하다.",
