      "region": "",
      "aliases": [],
      "description": "식물원(botanical garden, botanic garden)은 식물명으로 표시된 다양한 식물들의 수집, 재배, 보존, 전시 등을 위한 정원입니다. 선인장과 다른 다육식물, 허브정원, 세계 특수 지역의 식물 등과 같은 전문 식물 수집품을 포함할 수 있으며, 열대식물, 고산식물 또는 다른 외래 식물과 같은 특별한 수집품과 함께 온실과 그늘집이 있을 수 있습니다. 식물원의 방문객 서비스에는 관광, 교육 전시, 미술 전시회, 도서실, 야외 연극 및 음악 공연, 기타 오락 등이 포함될 수 있습니다. 식물원은 종종 대학이나 다른 과학 연구 기관들에 의해 운영되며, 식물 분류학이나 식물 과학의 다른 측면에 있는 헤르바리아와 연구 프로그램들을 종종 연관시켜왔다. 원칙적으로, 그들의 역할은 과학적 연구, 보존, 전시, 그리고 교육의 목적을 위해 문서화된 살아있는 식물의 컬렉션을 유지하는 것입니다.",
