      "aliases": [],
      "description": "그레이트배리어리프(Great Barrier Reef) 또는 대보초(大堡礁)는 오스트레일리아 북동부에 위치한 세계 최대의 산호초 지대입니다. 이것은 오스트레일리아의 해안 지형에서 가장 두드러진 특색입니다.2,600 km에 걸쳐 3,000위치: 오스트레일리아의 북동 퀸즐랜드주의 해안을 따라 발달한 산호초입니다. 면적 20만 7,000km2, 길이 약 2,000km, 너비 약 500~2,000m로 세계 최대의 산호초입니다. 북쪽은 파푸아뉴기니의 남안의 플라이강 어귀까지, 남쪽은 퀸즐랜드주의 레이디 엘리엇까지 이어져 있습니다. 산호초 대부분이 바다에 잠겨 있고, 일부가 바다 위로 나와 방파제와 같은 외관을 형성합니다. 초호는 수심 60m 이하의 대륙붕이며, 해저는 평탄하고 동쪽으로 약간 경사져 있습니다.",
