      "description": "데인트리 열대우림은 호주의 퀸즐랜드주의 동북쪽 해안 지역이며, 모스맨과 케언즈 북쪽에 위치해 있습니다. 대략 1200 제곱킬로미터 (460 제곱마일)이며, 데인트리는 호주 대륙에서 가장 큰 연결된 열대 우림 지역의 한 부분입니다. 데인트리 열대우림은 케언즈 지역을 가로지르는 퀸즐랜드 열대우림의 열대 습윤 지역의 한 부분입니다. 퀸즐랜드 열대 습윤 지역(데인트리가 한 부분인)은 세계에서 가장 오래되었고 살아남은 연결된 열대 우림입니다. 데인트리 강의 북쪽 해안선을 따라, 열대 우림이 바다의 바로 앞까지 뻗어져 있습니다. 2009년, Q150 행사의 일부분으로 데인트리 열대우림이 ‘자연 명소’의 역할로 퀸즐랜드 Q150 상징 중 하나로 선정되었습니다.",
