      "description": "울루루는 호주 중앙부의 붉은 사막에서 거대한 바위산처럼 솟은 사암 지형입니다. 햇빛의 방향과 날씨에 따라 붉은색, 주황색, 보랏빛으로 색이 달라 보입니다. 이곳은 아난구 원주민에게 매우 중요한 문화적·정신적 장소이며, 바위에는 오래전부터 이어져 온 이야기와 전통이 담겨 있습니다. 관광객의 울루루 등반은 금지되어 있으며, 주변을 걸으며 자연과 문화적 의미를 존중하는 방식으로 감상할 수 있습니다.",
