      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "카타추타는 올가스로도 알려져 있으며, 공식적으로 카타추타 / 올가 산으로 가제트에 등재되어 있습니다. 오스트레일리아 중앙의 노던 준주 남부에 위치한 앨리스스프링스에서 남서쪽으로 약 360 km (220 mi) 떨어진 곳에 있는 크고 둥근 암석 지형 또는 본하르트의 집합체입니다. 동쪽으로 25 km (16 mi) 떨어진 곳에 위치한 울루루 / 에어즈 록과 카타추타 / 올가스는 울루루-카타추타 국립공원 내의 두 주요 랜드마크를 형성합니다. 이 공원은 지역 원주민 공동체에게 신성한 곳으로 여겨진다. 카타추타 / 올가 산을 이루는 36개의 돔은 21.68 km2 (8.37 sq mi)의 면적을 덮고 있으며, 화강암과 현무암을 포함한 다양한 암석 유형의 자갈과 바위가 조립질 사암의 기질로 결합된 역암으로 구성된 퇴적암입니다.",
