      "description": "카카두 국립공원(Kakadu National Park)은 오스트레일리아 노던 준주의 보호구역입니다. 다윈에서 남동쪽으로 171 킬로미터 부근에 위치합니다. 이 공원은 노던 준주의 앨리게이터 리버스 안에 위치해 있습니다. 면적은 19,804 km2 (7,646 sq mi),이며 북쪽에서 남쪽으로 약 200km, 동쪽에서 서쪽으로 100km 이상을 덮고있습니다. 웨일스만한 크기이며 태즈마니아 크기의 약 3분의 1 크기이며 스위스의 약 절반 크기입니다. 세계에서 가장 생산성이 좋은 우라늄 탄광의 하나인 레인저 우라늄 광산이 이 공원을 둘러싸고 있습니다.",
