      "aliases": [],
      "description": "킹스 캐니언 국립공원(Kings Canyon National Park)은 미국 캘리포니아주 프레즈노군, 툴레어군에 있는 시에라네바다산맥 (미국) 남부에 있는 국립공원입니다. 원래 1890년에 '제너럴 그랜트 국립공원'(General Grant National Park)이라는 이름으로 설립된 이 공원은 1940년 3월 4일에 크게 확장되고 이름이 변경되었습니다. 이 공원의 이름을 딴 킹스 캐니언(Kings Canyon)은 깊이가 1마일(1,600m)이 넘는 울퉁불퉁한 빙하 계곡입니다. 다른 자연적 특징으로는 4,300m(14,000피트) 높이의 여러 봉우리, 높은 산 초원, 빠르게 흐르는 강, 세계에서 가장 큰 거삼나무 등이 있습니다. 킹스 캐니언은 세쿼이아 국립공원 북쪽에 인접해 있으며, 두 공원 모두 미국 국립공원관리청에서 세쿼이아 국립공원과 킹스 캐년 국립공원으로 공동 관리합니다.",
