      "description": "센트럴 파크는 미국 뉴욕주 뉴욕 맨해튼에 있는 도시 중심부의 공원입니다. 해마다 2,500만 명의 관광객이 이곳을 찾으며 미국 전역을 통틀어 가장 많은 사람이 찾는 공원으로 꼽힌다. 뿐만 아니라 영화나 TV 프로그램에 등장하는 공원의 모습은 전 세계적으로 센트럴 파크를 유명 장소가 되는 데 일조하였습니다. 공원 전체의 관할은 개인 비영리단체인 센트럴 파크 관리위(the Central Park Conservancy)에서 담당하며 뉴욕시와 함께 관리합니다. 공원은 북쪽으로 서부 110번 가(West 110th Street), 남쪽으로 서부 59번 가(West 59th Street), 서쪽으로 센트럴 파크 서부(Central Park West) 동쪽으로 5번 가(Fifth Avenue)에 접해 있습니다.",
