      "description": "엠파이어 스테이트 빌딩(Empire State Building)은 미국 뉴욕주 뉴욕 맨해튼섬 5번가와 34블록 일대에 위치하고 있는, 1931년에 지어진 아르 데코 양식의 건물입니다. 지상 102층에 높이는 381 m이며 1953년에 설치된 안테나 탑을 포함할 경우 443 m입니다. 86층의 콘크리트 건물 위의 16층 짜리 철탑은 본래 비행선의 계류탑을 목적으로 만들어졌으나 바람이 심해 비행선 정박이 위험하다는 이유로 거의 사용되지 않았으며 현재는 전망대와 방송용 안테나만이 위치해있습니다. 또한 영화 킹콩에서 킹콩이 안테나 탑에서 벌이는 장면으로도 유명하다. 엠파이어 스테이트 빌딩에는 73개의 엘리베이터가 있으며 모두 합친 길이는 무려 11 km나 된다. 또한 102층까지 1,860개의 계단이 있으며 6,500개의 창문이 있습니다.",
