      "aliases": [],
      "description": "메트로폴리탄 미술관은 미국 뉴욕주 뉴욕시에 위치한 세계적인 미술관입니다. 본관은 맨해튼 어퍼 이스트 사이드 5번가에 위치해 있으며, 분관으로 더 클로이스터스가 있습니다. 1866년에 파리에서 미국 독립기념일을 축하하기 위해 모인 미국인들의 회합에서 설립이 제안되어, 1870년에 소규모로 개관하였습니다. 1880년에 지금의 자리(1000 Fifth Avenue. New York, New York 10028 )로 이전하였으며, 기금을 통한 구입과 기증 등으로 소장 미술품은 급증하게 되었습니다. 지금은 회화와 조각, 사진, 공예품 등 300여만 점이 소장되어 있습니다. 메트로폴리탄 미술관의 특색은 그 소장 유물의 폭이 동서고금을 막론하는, 전 시대와 지역에 걸쳐있다는 점입니다. 또한 이러한 미술관이 국가나 정부 기관의 주도가 아닌 순수하게 민간이 주도하여 설립되었다는 점입니다.",
