      "description": "링컨 기념관은 미국의 수도 워싱턴 D.C.에 있는 미국의 국가 기념관으로 제 16대 대통령인 에이브러햄 링컨(Abraham Lincoln)을 기념하기 위해 지었고, 1922년 5월에 헌정되었습니다. 워싱턴 기념탑 건너편, 내셔널 몰의 서쪽 끝에 있습니다. 이 링컨 기념관은 많은 사람이 찾는 중요한 관광지로, 1930년부터는 인권이나 인종 관계의 상징적인 중심이 되어왔다. 건물 내부에는 대형 에이브러햄 링컨의 좌상 동상과 함께 링컨 대통령의 게티즈버그 연설문과 그의 두 번째 취임식 연설문이 새겨져 있습니다. 또한 이 기념관은 1963년 8월 28일, 마틴 루터 킹(Martin Luther King Jr.)이 일자리와 자유를 위한 워싱턴 인권 궐기 대회의 마지막 날에 연설했던 \"나는 꿈이 있습니다\"를 포함한 유명한 연설 장소로도 잘 알려져 있습니다.",
