      "name": "백악관",
      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "펜실베이니아 거리 NW에 위치한 미합중국 대통령의 집무실 겸 관저입니다. 1800년 제2대 존 애덤스 대통령 이후로 미합중국 대통령의 주거지로 이용되어 왔으며, 집무·외국사절 접견·일상생활 등 모든 일을 여기서 합니다. '백악관'이라는 명칭은 미국 대통령과 행정관, 최고 보좌관들의 행위 및 입장을 일컫는 환유 표현으로 사용되기도 합니다. 백악관 부동산은 미국 국립 공원국이 소유한 국립 유적지와 대통령 공원의 일부입니다. 2007년, 백악관은 미국인들이 가장 선호하는 건축물 목록 중, 미국 건축 기관으로 두 번째 자리를 차지했습니다. 백악관의 모습은 미국 20달러 지폐의 뒷면에 그려져 있습니다. 2016년 5월 입구 검문소에서 총격사건이 일어나 일대가 폐쇄조치가 된 사건이 있었다.",
