      "description": "미국 국회의사당(United States Capitol)은 미국 연방 정부의 입법부인 미국 의회가 있는 건물입니다. 워싱턴 D.C.의 내셔널 몰 동쪽 끝에 있는 캐피틀힐 위에 자리잡고 있습니다. 국회의사당은 지리상 컬럼비아 특별구의 중심에 있지는 않으나, 4개 지구를 가르는 원점이 된다. 초기 건물은 1800년에 완공되었습니다. 허나 1814년에 영국군이 쳐들어와 워싱턴 D.C에 불을 지르면서 의사당도 함께 전소하여 미국 초기에는 제대로 된 기능을 하지 못하였습니다. 의사당은 약 5년 후에 다시 복구되었으며, 점차 미국의 국력이 팽창함에 따라 건물의 규모도 점점 커져갔다. 특히 위에 거대한 돔이 얹혀졌고, 상원 회의장이 북쪽 건물에, 하원 회의장이 남쪽 건물에 각각 설치되며 미합중국의 정식 의사당 역할을 맡게 되었습니다.",
