      "description": "요세미티 국립공원(Yosemite National Park)은 미국 캘리포니아주 시에라네바다산맥 서부에 위치한 국립공원입니다. 미국 국립공원관리청이 관리하는 이 공원의 면적은 3,026.87km2입니다. 1984년 유네스코 세계유산으로 지정되었으며 요세미티는 화강암 절벽, 폭포, 깨끗한 개울, 자이언트세쿼이아숲, 호수, 산맥, 목초지, 빙하, 생물 다양성으로 국제적인 인지도가 있는 편입니다. 이 공원의 약 95%가 자연 보호 구역입니다. 한 해 평균 4백만 명의 방문자가 있으며 대부분의 관광객은 15km2의 요세미티 계곡에서 시간을 보낸다. 이 공원은 2016년 방문 기록을 세웠는데, 사상 최초로 500만 명을 능가하는 방문객 수를 기록하였습니다.",
