      "aliases": [],
      "description": "브라이스 캐니언 국립공원(Bryce Canyon National Park)은 미국 유타주 남부에 있는 국립공원입니다. 브라이스 캐니언은 수만개의 섬세한 첨탑을 가진 여러 개의 반원형 극장의 집단과 같은 모습입니다. 이곳의 수만개를 헤아리는 기묘한 첨탑 하나하나는 모두 물의 힘에 의해 만들어진 것입니다. 바다밑에 있을 때 토사가 쌓여서 형성된 암석이 지방에 우뚝 솟은 후 빗줄기와 흐르는 물의 힘에 의해 다시 본래의 토사로 변하여 흘러내려가는데 비교적 단단한 암석만 침식되지 않고 남아서 무수한 첨탑이 생긴 것이라고 합니다. 브라이스 캐니언을 형성하고 있는 반원형 극장의 가장자리는 50년 간격으로 약 1피트씩 후퇴하고 있는데 이러한 현상은 지질학적으로 볼 때 대단히 빠른 속도로 진행되는 것으로 보고 있습니다.",
