      "aliases": [],
      "description": "모뉴먼트밸리(Monument Valley)는 미국 서남부 유타주의 남부로부터 애리조나주 북부에 걸친 지역 일대의 명칭으로, 나바호족의 언어로는 '쎄 비니스게이(Tse Bii Ndzisgaii)'라고 부르는데, '쎄(Tse)'는 돌이라는 뜻이고, '비니스게이(Bii Ndzisgaii)'는 하얀색하고 같다는 뜻으로, 호주의 울루루처럼 사암지대로 구성되어 있습니다. 메사라고 하는 테이블형의 대지이며 한층 더 침식이 진행되었으며, 예전에 미국 서부 영화에도 단골로 등장했었다. 뷰트라고 하는 바위 산이 점재해, 마치 기념비(모뉴먼트)가 줄지어 서있는 듯한 광경은 장엄함 그 자체가 아닐 수 없다. 예부터의 나바호족 거주지역으로, 거류지가 된 현재는, 그 일부는 나바호족관할 아래 일반적으로 개방하는 형태로 공개되고 있어 나바호족의 성지라고도 불려 1년 내내 관광객들의 발길이 끊이지 않으며, 유네스코 세계 자연유산에도 등재되어 있습니다.",
