      "description": "아치스 국립공원(Arches National Park)은 미국 유타주 동부의 국립공원입니다. 이 공원은 유타주 모압으로부터 북쪽으로 6킬로미터 떨어진 콜로라도강에 인접해 있습니다. 2,000개 이상의 천연교가 이 공원에 위치해 있으며 그 중 잘 알려진 것으로 델리케이트 아치가 포함된다. 그 외에 다양하고 고유한 지리적 자원과 모습들이 보인다. 이 공원은 세계에서 천연 아치형 구조물이 가장 많이 밀집한 곳입니다. 이 공원은 콜로라도고원에 위치한 310.31제곱 킬로미터 면적의 높은 지대 사막으로 구성되어 있습니다. 최고 높이는 엘리펀트 버트의 1,723미터, 가장 낮은 지점은 방문자 센터의 1,245미터입니다. 연간 강수량은 평균 10인치 미만입니다.",
