      "region": "",
      "aliases": [],
      "description": "시카고는 뉴욕, 로스앤젤레스에 이어 미국에서 3번째로 큰 도시이며, 일리노이주 및 미국 중서부에서 가장 큰 도시로 그 인구는 270만 명입니다. 시카고 랜드라고 불리는 이 지역의 광역 도시권은 950만 명의 인구와 함께 미국에서 3번째로 큰 대도시권입니다. 시카고는 쿡 군의 군청소재지이기도 하다. 오대호와 미시시피강을 이어주는 육로 수송지로 발전하면서 19세기 중반부터 빠르게 성장한 시카고는 1837년 시로 승격되었습니다. 오늘날 시카고는 경제, 무역, 산업, 과학, 통신, 교통의 국제적인 중심지입니다. 시카고 오헤어 국제공항은 세계에서 2번째로 혼잡한 공항이며, 미국에서 가장 많은 고속도로가 지나간다. 2012년 시카고는 세계화와 세계도시조사망(GaWC)에서 알파 글로벌 도시로 평가되었고, 2014년 글로벌 도시 지수에서는 7위에 선정되었습니다.",
