      "description": "하와이 화산 국립공원(Hawai Volcanoes National Park)은 미국 하와이 제도의 하와이섬에 있는 킬라우에아산, 순상화산인 마우나로아산(mauna loa)에 있는 국립공원으로, 주로 킬라우에아산이 많이 차지합니다. 킬라우에아산은 정상에 박물관이 있고, 용암을 직접 볼 수 있도록 해주고, 사람들이 용암을 분출하는 모습이나 용암이 바다로 흘러들어가는 것을 볼 수 있게 해준다. 마우나로아산은 등산하여 정상에 있는 칼데라를 보여준다. 킬라우에아산과 마우나로아산은 서로 붙어있기 때문에 마우나로아산도 해당된다. 이 둘중에 킬라우에아산은 세계 최대의 활화산이라고 합니다. 정상에 지름 6km의 거대한 칼데라가 있고, 그 안에 있는 대형 화구인 할레마우마우 분화구를 직접 관찰할 수 있습니다.",
