      "description": "고창 갯벌은 서해안의 조수간만 차로 바닷물이 들어왔다 빠지면서 넓게 드러나는 자연 생태계입니다. 갯벌의 진흙과 모래 사이에는 조개와 게, 작은 저서생물들이 살고, 이들을 먹이로 삼는 물새들이 찾아옵니다. 밀물 때와 썰물 때의 모습이 크게 달라져 같은 장소에서도 전혀 다른 풍경을 볼 수 있습니다. 고창 갯벌은 2021년 유네스코 세계자연유산으로 등재된 ‘한국의 갯벌(Getbol, Korean Tidal Flats)’의 구성 지역 중 하나입니다. 갯벌의 아름다움은 넓은 풍경뿐 아니라 수많은 생물이 이어 만드는 먹이 관계와 철새의 이동을 지탱하는 데 있습니다. 사진으로는 썰물의 갯벌 전경, 물길, 갯벌 생물과 철새를 함께 살펴보면 좋습니다.",
