      "description": "붉은 요새는 인도의 델리에 있는 성입니다. 현재 유네스코 문화유산으로 등재되어 있습니다. 델리 북쪽 야무나 강변에 위치한 제7의 도성 샤자하나바드(Shahjahanabad) 동쪽에 서 있는 성채인 레드 포트(Red Fort)는 샤 자한 황제가 1639년에 건설을 시작하였으며 1648년 아그라 성에서부터 이곳으로 천도하였습니다. 이 성채는 적색사암으로 축조되어 델리 성 레드 포트라 지칭되고 있습니다.",
