      "description": "연꽃 사원 또는 로터스 템플(Lotus Temple)은 인도 뉴델리에 있는 바하이 예배당입니다. 연꽃을 닮은 모양으로 유명하며, 도시의 주요 명소가 되었습니다. 모든 바하이 예배당과 마찬가지로 연꽃 사원은 종교나 기타 자격에 관계없이 모든 사람에게 개방된다. 이 건물은 3개씩 묶여 9개의 면을 형성하는 27개의 독립된 대리석 \"꽃잎\"으로 구성되어 있으며, 높이가 34미터가 조금 넘는 중앙 홀로 이어지는 9개의 문이 있습니다. 연꽃 사원은 수많은 건축상을 수상했으며 여러 신문과 잡지 기사에도 소개되었습니다.",
