      "description": "하와마할은 인도 라자스탄주 자이푸르시에 위치한 궁전입니다. 1799년 자이푸르 왕국의 마하라자 사와이 프라탑 싱이 지었으며, 적색과 분홍색 사암으로 지어진 것이 특징으로, 수많은 창과 발코니로 뒤덮여 벌집을 연상시킨다. '바람의 궁전' (Palace of winds)라는 별명으로도 알려져 있습니다. 거리에서 바라볼 때 마주하는 하와마할의 아름다운 외관을 두고 흔히 건물의 정면이라 생각하는 경우가 많지만, 실제 입구는 반대쪽에 있기에 건물의 후면에 해당된다. 자이푸르 왕궁의 한쪽 구역에 자리해 '제나나'(Zenana)라고 부르는 여성용 생활공간 (규방)까지 이어져 있습니다. 자이푸르 왕궁에는 하와마할 외에도 이 궁전과 맥락을 같이 하는 석조물과 소형창, 아치 구조물 등이 있으며, 정교하게 조각된 처마장식 등도 건축적인 볼거리로 꼽힌다.",
