      "aliases": [],
      "description": "잔타르 만타르는 육안으로 관측할 수 있도록 설계된 석조 천문 관측 기구들의 집합체다. 1724년에서 1735년 사이에 인도에 5개의 잔타르 만타르가 건설되었습니다. 모두 수학, 건축, 천문학에 깊은 관심을 가졌던 마하라자 자이 싱 2세의 명령에 따라 건설되었습니다. 북인도의 자이푸르, 델리, 우자인, 바라나시, 그리고 마투라(현재는 존재하지 않음)에 총 5개의 잔타르 만타르가 건설되었습니다. 이 모음집 또는 미슈라 얀트라 (‘혼합 도구’)는 최대 19개의 서로 다른 천문 관측 기구를 모아놓은 것입니다. 가장 큰 사례는 분점 해시계로, 자이푸르의 기구 모음 중 하나이며 지구의 자전축과 평행한 빗변을 가진 거대한 삼각형 규표로 구성되어 있습니다. 규표의 양쪽에는 적도 평면과 평행한 원의 사분의가 있습니다.",
