      "description": "인도 북부 카슈미르의 스리나가르에 자리한 달 호수는 물 위에 떠 있는 집배와 작은 배들로 유명합니다. 현지에서 시카라라고 부르는 길쭉한 나룻배는 호수의 교통수단이자 여행의 상징입니다. 호숫가에는 무굴 시대 정원이 있고, 물 위에서는 꽃과 채소를 파는 사람들도 만날 수 있습니다. 멀리 산이 둘러싼 수면에 계절마다 다른 빛이 비치는 모습은 카슈미르가 오래도록 아름다운 계곡의 땅으로 알려진 이유를 전해 줍니다.",
