      "description": "발리 우붓의 원숭이 숲에는 긴꼬리원숭이들이 나무 사이와 오래된 돌길을 자유롭게 오갑니다. 이곳은 단순히 야생동물이 모인 숲이 아니라 발리 사람들에게 중요한 사원과 숲이 함께 있는 문화 공간입니다. 이끼 낀 돌조각과 거대한 나무뿌리는 오랜 세월 숲과 사람이 공존해 온 모습을 보여 줍니다. 원숭이는 사람의 물건에 관심을 보이기도 하므로, 이 숲에서는 야생동물의 생활을 존중하는 태도가 특히 중요합니다.",
