      "description": "발리의 뜨갈랄랑에는 산비탈을 따라 초록색 논이 층층이 이어집니다. 평지가 적은 경사지에서도 벼를 재배하려고 사람들이 오랫동안 흙을 다듬고 물길을 만들었습니다. 발리의 전통 관개 체계인 수박은 물을 공평하게 나누고 농사 시기를 조정하는 공동체의 지혜와 연결됩니다. 멀리서 보면 계단처럼 보이는 논은 아름다운 풍경일 뿐 아니라 오랜 세월 사람들의 손으로 만든 생활의 흔적입니다.",
