      "description": "아테네는 그리스의 수도이자 최대의 도시이며, 아티키 주의 중심 도시입니다. 세계적으로 오래된 도시이며, 역사 시대가 개막한 지 3,400년에 이른다. 대략 기원전 11세기 ~ 7세기부터 인간이 정착해 살았던 흔적이 남아있습니다. 고대 아테네는 강력한 도시 국가였으며, 고대 아테네의 부는 기원전 5세기부터 아테네와 연합을 시작한 피레아스 항구를 통해서 유입됐다. 아테네 행정 구역내 인구는 664,046명(2011년)이며, 면적은 39 평방 킬로미터입니다. 아테네의 도시 경계 바깥을 아우른 도시권 전체 인구는 3,130,841 명(2001년)이며, 면적은 412 평방 킬로미터에 이른다. 유럽연합 통계국에 따르면, 아테네 대도시권역(LUZ, Larger Urban Zone)은 유럽 연합 내에서 7번째로 인구가 많다고 합니다.(3,753,783명, 2011년) 혼잡한 국제 대도시인 아테네는 그리스의 경제, 금융, 산업, 정치, 문화의 중심지이며, 세계 도시 중 베타+급 도시로 등재되어 있습니다.",
