      "description": "그리스의 고대 올림피아는 오늘날 세계인이 즐기는 올림픽의 뿌리가 시작된 장소입니다. 고대 그리스 사람들은 제우스 신을 기리는 제전의 일부로 달리기와 여러 운동 경기를 열었습니다. 경기장은 관중이 앉던 흙 언덕과 선수들이 달리던 길을 통해 당시의 모습을 전합니다. 올림픽 경기는 단순한 놀이가 아니라 그리스 도시국가들이 모여 경쟁하고 교류하는 중요한 행사였습니다. 지금도 근대 올림픽 성화 채화식이 이곳에서 열립니다.",
