      "description": "에피다우로스 극장(그리스어: Θέατρο της Επιδαύρου)은 고대 그리스의 도시인 에피다우로스에 세워진, 고대 그리스의 신 아스클레피오스에게 봉헌된 성소의 남동쪽에 있는 극장입니다. 기원전 4세기 말에 지어졌으며 음향학적, 미학적으로 가장 뛰어난 고대 그리스의 극장 중 하나로 지적된다. 1988년 아스클레피우스 신전과 함께 유네스코 세계유산에 등재되었습니다.",
