      "description": "크노소스(그리스어: Κνωσός)는 그리스의 크레타섬에 있는 현존하는 것들 중 가장 규모가 큰 청동기 시대 유적지로, 유럽 최고(最古)의 도시라 불린다. 미노스 문명의 중심지로 알려져 있습니다. 크노소스라는 이름은 크레타의 주요 도시를 기록한 고대 그리스 문서에서도 발견될 정도로 그 내력이 유구하며, 그 존재는 청동기 시대부터 전승 기록과 초기 발굴 장소 근처와 케팔라 언덕에서 대량으로 발견된 로마 동전에 그려진 미노타우로스와 라비린투스, 미노스의 묘사로 확인할 수 있으며, 크노시온(Knosion)·크노스(Knos)라는 이름으로 알려져 있었다는 것을 알 수 있으며, 로마인들은 크노소스를 식민지로 삼았었던 것으로 추측된다.",
