      "description": "술탄 아흐메트 모스크(튀르키예어: Sultan Ahmet Camii)는 튀르키예의 이스탄불에 있는 대표적인 모스크로, 세계문화유산인 이스탄불 역사지구의 유서깊은 건축물 가운데 하나입니다. 오스만 제국의 제14대 술탄 아흐메트 1세의 명령에 따라 1609년부터 착공에 들어가 7년이란 공사기간 끝에 1616년에 완성되었습니다. 세계에서 가장 아름다운 모스크라는 평가를 받고 있습니다. 모스크 안 벽면을 온통 뒤덮은 푸른빛을 띠는 도자기 타일 때문에 블루 모스크라는 애칭으로 널리 알려져 있습니다.",
