      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "돌마바흐체 궁전(튀르키예어: Dolmabahçe Sarayı)은 튀르키예 이스탄불에 있는 오스만 제국 궁전입니다. 화려한 석조 건축물로 세워진 이 궁전은 원래 목조 건물이었으나 1814년 대화재로 대부분 불타고 31대 술탄 압둘마지드 1세가 1856년에 재건했습니다. 1843년에 착공해서 1859년에 완공했으며 베르사유 궁전을 모델로 했습니다. 유럽에서 보낸 수많은 현상품과 호화롭게 꾸며진 사방의 벽들을 보면 당시 생활을 짐작할 수 있습니다. 오스만 제국 후기 술탄 6명이 일부 사용했습니다. 세람르크는 술탄이 공무를 보고 각국 대사를 접견하던 장소로 남자만 출입이 가능했습니다. 하렘은 왕실 가정으로 술탄과 가족이 살았으며 튀르키예 초대 대통령인 무스타파 케말 아타튀르크도 이 곳을 관저로 쓰다가 1938년 11월 10일 오전 9시 5분에 집무실에서 죽었다.",
