      "description": "예레바탄(튀르키예어: Yerebatan)은 튀르키예 이스탄불에 있는 동로마 제국 시대의 지하 저수지입니다. 바실리카 시스턴(Basilica Cistern)이라는 이름으로도 널리 알려져 있습니다. 지하 궁전은 현존하는 동로마 제국의 저수지 가운데서도 이곳이 가장 최대라고 합니다. 오늘날에는 이스탄불 역사지구의 한 축으로서 세계유산에 등록되어 있으며, 일반에 공개하고 있습니다. 아야 소피아로부터 맞은편 방향으로 디반 욜루의 맨 위쪽 부근에 위치해 있습니다. 지하 궁전은 1987년에 수백 년 동안 쌓인 진흙과 폐물을 제거하는 작업을 벌이면서 복원되었습니다. 본래 황실 수도 공급을 원활히 하기 위한 목적으로 콘스탄티누스 대제 때에 공사를 시작하여 유스티니아누스 1세 때인 532년까지 진행되었다고 합니다.",
