      "description": "안네 프랑크의 집(네덜란드어: Anne Frankhuis)은 네덜란드 암스테르담에 있는 박물관으로, 1942년부터 1944년까지 유대인이었던 안네 프랑크가 숨어 살았던 집입니다. 안네가 있었던 다락방 및 안네의 일기, 사진 등이 그대로 보존되어 있습니다. 안네 프랑크 재단이 관리 운영을 실시하고 있습니다. 나치 정권의 학살에 관한 잔혹한 자료와 사진 등을 전시하고 있는 자료관도 있습니다.",
