      "name": "반 고흐 미술관",
      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "반 고흐 미술관은 네덜란드 암스테르담 남부의 뮈세윔플레인 광장에 있는, 빈센트 반 고흐와 그의 동시대 예술가들의 작품을 전문으로 다루는 미술관입니다. 암스테르담 시립 미술관, 암스테르담 국립미술관, 콘세르트헤바우와 인접해 있습니다. 이 미술관은 1973년 6월 2일에 개관했으며, 이 미술관의 건물은 헤리트 리트펠트와 구로카와 기쇼가 설계했습니다. 이 미술관은 세계에서 가장 큰 규모의 반 고흐 회화 및 소묘 컬렉션을 보유하고 있습니다. 2017년에는 230만 명의 방문객이 방문하여, 네덜란드에서 가장 많은 방문객을 기록했으며, 세계에서 23번째로 방문객이 많은 미술관으로 기록되었습니다. 2019년, 반 고흐 미술관은 반 고흐의 삶과 작품을 다루는 기술 기반의 몰입형 전시인 《반 고흐: 몰입형 체험》(Meet Vincent Van Gogh Experience)를 선보여 전 세계 순회 전시를 진행하고 있습니다.",
