      "description": "요르단(아랍어: أردنّ 우르둔)은 중동에 있는 입헌 군주국입니다. 정식 국명은 요르단 하심 왕국(아랍어: المملكة الأردنيّة الهاشميّة 알맘라카 알우르두니야 알하시미야)입니다. 수도는 암만이며, 이라크, 팔레스타인, 이스라엘, 사우디아라비아, 시리아와 국경을 접합니다. 약 26km의 해안선이 홍해의 북쪽 아카바만에 접합니다. 이 해안선을 끼고 있는 도시 아카바에는 요르단 유일의 항구가 있습니다.",
