      "description": "평화궁(Peace Palace)은 네덜란드 헤이그에 위치한 건물입니다. 국제사법재판소, 상설중재재판소, 헤이그 국제법 아카데미, 평화궁 도서관이 위치해 있습니다. 미국 철강 재벌 앤드루 카네기가 건설 자금을 기부했습니다. 북위 52.0866° 동경 4.2955° ﻿ / 52.0866; 4.2955에 위치해 있습니다. 네덜란드는 17세기에 해양 진출이 활발해져서 신흥 해양강국이 되었으며, 이러한 때에, \"국제법의 아버지\"라고 불리는 그로티우스를 배출합니다.",
