      "description": "델프트는 네덜란드의 운하와 벽돌 건물이 아름다운 오래된 도시입니다. 이곳은 하얀 도자기에 파란 무늬를 그린 '델프트 블루'로 유명합니다. 17세기 네덜란드 상인들이 아시아의 도자기에 매료되면서 현지 장인들도 독특한 청백색 도자기를 발전시켰습니다. 화가 요하네스 페르메이르가 태어나고 활동한 도시로도 알려져 있으며, 그의 그림에는 조용한 일상과 빛을 바라보는 섬세한 시선이 담겨 있습니다. 운하 옆 오래된 집과 교회, 도자기 공방은 한때 무역과 예술이 번성했던 델프트의 모습을 전합니다.",
