      "description": "유로마스트(Euromast)는 네덜란드 로테르담에 위치한 관측탑으로, 휴 마스칸트가 설계하여 1958년에서 1960년 사이에 건설되었습니다. 이 탑은 1960년 플로리아드를 위해 특별히 건립되었으며, 2010년부터는 국가 기념물로 등재되었습니다. 탑은 내부 직경 9 m (30 ft), 벽 두께 30 cm (12 in)의 콘크리트 구조물입니다. 안정성을 위해 1,900,000 kg (4,200,000 lb)의 콘크리트 블록 위에 세워져 무게 중심이 지면 아래에 있도록 설계되었습니다. 지상 96 m (315 ft) 높이에는 \"까마귀 둥지\"라 불리는 전망대와 레스토랑이 있습니다. 원래 높이는 101 m (331 ft)로 로테르담에서 가장 높은 건물이었다. 1968년 완공된 에라스무스 의료 센터(Erasmus MC, 113.5 m, 372 ft)에 그 자리를 내주었으나, 1970년 건물 꼭대기에 85 m (279 ft)의 스페이스 타워가 추가되면서 다시 가장 높은 건물이 되었습니다.",
