      "description": "호헤 벨루웨 국립공원은 네덜란드 중부에 펼쳐진 숲과 초원, 모래언덕이 어우러진 보호지역입니다. 바다와 가까운 나라에서 넓은 모래밭이 나타난다는 점이 특히 뜻밖입니다. 나무가 적은 모래 지역에서는 바람이 모래를 옮기며 풍경을 계속 바꿉니다. 공원에는 사슴과 멧돼지 같은 야생동물이 살아갑니다. 공원 안의 크뢸러뮐러 미술관은 빈센트 반 고흐의 작품을 많이 소장한 곳으로 유명합니다. 자연 보호와 미술 수집을 함께 실현하려 했던 부부의 뜻이 오늘날까지 이어지는 특별한 장소입니다.",
