      "description": "크뢸러 뮐러 미술관은 네덜란드 오테를로의 호허 벨뤼베 국립공원에 위치한 국립 미술관이자 조각공원입니다. 미술 수집가 헬레네 크뢸러 뮐러가 남편과 함께 소유했던 광활한 부지(현재의 국립공원) 안에 설립한 이 미술관은 1938년에 개관했습니다. 반 고흐 미술관에 이어 세계에서 두 번째로 많은 빈센트 반 고흐의 회화 작품을 소장하고 있습니다. 2015년에는 380,000명의 방문객이 다녀갔다.",
