      "description": "네덜란드 하를럼의 흐로터 마르크트는 오래된 도시 한가운데에 펼쳐진 넓은 시장 광장입니다. 광장 옆에는 높다란 성 바보 교회가 서 있고, 주변의 벽돌 건물들은 하를럼이 상업과 수공업으로 번성했던 세월을 전합니다. 중세부터 사람들이 물건을 사고팔고 소식을 나누던 이곳은 지금도 도시 생활의 중심입니다.\n\n하를럼은 한때 직물과 맥주 양조로 이름났고, 네덜란드 황금시대에는 미술이 꽃피었습니다. 초상화로 유명한 프란스 할스가 활동했던 도시이기도 합니다. 시장이 열리는 날에는 오래된 광장에 다시 가게와 사람들로 활기가 넘칩니다. 수백 년의 건물 사이로 오늘의 일상이 자연스럽게 이어지는 곳입니다.",
