      "description": "쇤브룬궁은 과거 오스트리아 제국의 로코코 형식 여름 별궁으로 1,441개의 방이 마련되어 있습니다. 오스트리아에서 가장 큰 궁전이자 방문객이 가장 많은 유적지 중 하나이며, 문화적으로도 가장 뜻 깊은 곳 중 하나입니다. 쇤브룬 궁전의 정원은 한 시절 유럽을 호령했던 합스부르크 가문의 품격과 취향을 고스란히 보여주고 있습니다. 50만평에 이르는 그 대지와 궁궐은 1996년 유네스코 세계 문화 유산으로 선정되었으며 쇤브룬 공원 안에 있는 빈 동물원은 세계에서 가장 오래된 동물원입니다. 18세기 중엽 마리아 테레지아 여제의 여름 별장으로 지어진 쉰브룬궁은 1892년부터 빈 13구역 히칭에 위치해 있습니다. 이 궁전의 이름은 1619년 마티아스 황제가 사냥하다가 샘터를 발견했을 때 'Welch’ schöner Brunn' (이 얼마나 아름다운 샘인가!) 라고 외쳤다는 일화에서 유래되었다고 합니다.",
