      "description": "벨베데레궁은 오스트리아의 궁전으로서 빈 남동쪽에 있는 바로크 양식 궁전입니다. 왕가는 1697년 부지를 사들이고 사보이의 왕자 오이겐(Eugen von Savoyen)이 거대한 공원을 우선 조성하였습니다. 벨베데레 궁전은 도시 근교에서 왕족이 보낼 수 있는 대표적인 건물로 떠오르게 되었습니다. 1714년 건축이 시작되어 일단 틀을 닦고 정원도 만들게 되었습니다. 그 주변으로는 오랑제리와 그림을 전시하는 공간을 만들었다. 건축은 요한 루카스 폰 힐데브란트가 맡았으며 그는 지금까지도 오스트리아의 바로크 양식을 극대화한 거장으로 손꼽힌다. 그와 함께 베네치아 출신의 조각가 죠반니 스타네티가 함께 하였습니다. 하부 벨베데레 궁전의 건설은 1716년 완공되었으며 천정은 마르니코 알트몬테라는 화가가 완성하였습니다.",
