      "description": "빈의 호프부르크 왕궁은 오랫동안 합스부르크 왕가가 권력을 행사하던 중심지였습니다. 한 번에 완성된 궁전이 아니라, 여러 세기에 걸쳐 새로운 건물과 뜰이 덧붙으면서 거대한 궁전 단지가 되었습니다. 황제의 거처뿐 아니라 행정과 의식이 이루어지던 공간이었으며, 오늘날에는 박물관과 공공기관 등이 자리합니다. 화려한 방과 황실의 유물에는 유럽 여러 지역을 다스렸던 왕가의 역사가 남아 있습니다. 옛 황궁이 현대 오스트리아의 중심 공간으로 계속 쓰인다는 점도 인상적입니다.",
