      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "빈 국립 오페라 극장은 음악의 도시 빈을 대표하는 오페라 극장입니다. 제2차 세계대전 이후 10년에 걸쳐 정부, 시청, 시민들이 눈물겨운 협력을 한 보람으로 전쟁에서 재건되어 1955년 가을에 복구되어 개장하였습니다. 궁정가극장의 후신인 이 극장을 사랑하는 빈 시민의 희망에 따라 외관은 옛모습대로 복원하였으며 외벽의 새로움을 피하기 위하여 상당한 비용을 들여 고색창연한 옛모습의 아취를 살려 옛 도시다운 우아함을 보였습니다. 그러나 시설은 최신식이며 객석의 3배나 되는 광대한 무대는 몇 개로 구분되어 짧은 시간에 자유롭게 움직여 장면 전환을 빨리 할 수 있도록 장치하였습니다. 객석은 2,200여개로 1층 뒤쪽에 입석이 있고 천장 객석에는 열렬한 팬들을 위해 악보를 볼 수 있도록 배려가 되어 있습니다.",
