      "aliases": [],
      "description": "알베르티나는 오스트리아 빈 인네레슈타트(제1구)에 있는 미술관입니다. 약 65,000점의 소묘와 약 100만 점의 옛 거장의 판화를 비롯하여 현대 그래픽 작품, 사진, 건축 도면 등을 소장하고 있어 세계에서 가장 크고 중요한 판화 및 소묘 전시실 중 하나를 갖추고 있습니다. 판화 외에도 임대로 장기 확보한 상설 기증 컬렉션 두 개를 보유하고 있으며, 이 중 인상주의 및 20세기 초반 미술 작품 일부는 상설 전시되고 있습니다. 2025년 관람객 수는 1,037,347명으로 2024년 대비 3% 감소했으나, 코로나19 팬데믹 이전인 2019년보다는 4% 증가했습니다. 세계에서 가장 많이 방문한 미술관 순위에서 74위를 기록했습니다. 알베르티나는 세 곳의 분관으로 구성되어 있다: 알베르티나 본관: 알베르티나의 본관은 합스부르크 가문의 역사적 거주지였던 알브레히트 대공 궁전(Palais Erzherzog Albrecht)에 위치해 있습니다.",
