      "name": "할슈타트",
      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "할슈타트는 오스트리아 오버외스터라이히주 그문덴군의 마을입니다. 할슈타트호에 가까이 있으며 알프스 기슭의 호수 지역 잘츠카머구트 지방의 가장 안쪽에 위치하는 경승지입니다. 유네스코 세계유산으로 등재되어 있고 마을의 꼭대기에 위치한 공동묘지에서 출토된 철기 시대 유물들로 유럽의 초기 철기 문화를 일컫는 \"할슈타트 문화\"가 이에서 유래되었습니다. 동화 속의 호수마을과 같은 모습으로 알려져 있는 할슈타트는 오스트리아의 9개의 주 중에서 오버외스트라이히 주에 속하는 마을입니다. 지리적으로는 할슈타트 호의 남서쪽, 다흐슈타인 산맥의 서쪽에 위치하고 있어서, 산과 호수가 어우러진 자연 경관이 아름답다. 할슈타트는 자연 경관 뿐 아니라 역사적 가치가 유명하다. BC 2000년부터 형성되었던 전 세계 최초의 소금광산으로 유명하며, 이를 통해 얻은 경제적 풍요로움을 바탕으로 BC 1000년부터 BC 500년의 철기 문화가 나타났고, 할슈타트의 분묘 유적에는 이러한 흔적들이 남아있습니다.",
