      "description": "오스트리아 다흐슈타인 산악지대의 얼음동굴에서는 산속 깊은 곳에 얼음으로 이루어진 신기한 풍경이 펼쳐집니다. 빗물과 눈 녹은 물이 석회암의 틈을 따라 오랜 세월 흘러 동굴을 만들었고, 차가운 공기가 머무는 곳에는 얼음이 쌓이거나 다시 얼어붙습니다.\n\n동굴 안의 얼음기둥과 얼음벽은 고정된 조각상이 아닙니다. 계절마다 들어오는 공기와 물의 양에 따라 조금씩 자라고 녹으며 모양을 바꿉니다. 땅 위에서는 여름 햇살이 내리쬐어도 동굴 내부에는 겨울 같은 풍경이 남습니다. 다흐슈타인 일대는 웅장한 알프스 산맥과 호수, 오래된 산촌 풍경으로도 알려져 있습니다.",
