      "description": "인스브루크의 황금지붕은 오스트리아 티롤 지역 구시가지에 있는 작은 발코니 지붕입니다. 이름과 달리 순금 덩어리로 만든 것은 아니며, 금빛을 낸 구리 기와 수천 장이 지붕을 덮고 있습니다. 15세기 말 황제 막시밀리안 1세 시대에 만들어진 이 발코니에서는 광장에서 열리는 축제와 행사를 내려다볼 수 있었습니다. 지붕 아래에는 당시 왕실의 모습을 전하는 장식도 남아 있습니다. 거대한 궁전이 아니라 작은 지붕 하나가 도시의 상징이 된 이유는, 반짝이는 외관과 그 안에 담긴 황제 시대의 역사 때문입니다.",
