      "aliases": [],
      "description": "오스트리아 인스브루크의 암브라스 성은 높은 산을 배경으로 서 있는 르네상스 시대의 성입니다. 16세기 티롤을 다스리던 페르디난트 2세 대공은 이 성에 특별한 수집품을 모았습니다. 무기와 갑옷뿐 아니라 세계 각지에서 들어온 희귀한 물건과 예술품까지 한자리에 모아 전시했습니다.\n\n이러한 수집실은 오늘날 박물관의 초기 모습으로 평가됩니다. 성 안의 스페인 홀은 화려한 초상화와 장식으로 유명하며, 방마다 당시 귀족들이 무엇을 신기하게 여겼는지 드러납니다. 암브라스 성은 단순한 방어 시설을 넘어 르네상스 사람들이 세계를 이해하려 했던 호기심을 담은 공간입니다.",
