      "aliases": [],
      "description": "그로스글로크너 고산도로는 오스트리아 알프스의 높은 산들을 지나가는 구불구불한 길입니다. 오스트리아에서 가장 높은 산인 그로스글로크너와 인근의 빙하를 가까이 만날 수 있는 도로로, 가파른 산비탈을 따라 급커브가 이어집니다. 1930년대에 완성된 이 길은 당시로서는 매우 어려운 산악 토목공사였습니다.\n\n도로가 높아질수록 숲이 줄어들고 풀밭과 바위가 나타나며, 먼 봉우리에는 여름에도 눈이 남습니다. 알프스마멋이나 산양이 사는 고산지대의 자연도 이어집니다. 겨울에는 눈이 많이 쌓이기 때문에 도로가 계절에 따라 닫히기도 합니다. 한 길 위에서 산의 여러 계절과 높이에 따른 풍경 변화를 느낄 수 있습니다.",
