      "region": "",
      "aliases": [],
      "description": "오스트리아의 멜크 수도원은 도나우강을 내려다보는 언덕 위에 서 있는 거대한 베네딕도회 수도원입니다. 밝은 노란빛 건물과 높이 솟은 성당은 먼 곳에서도 눈에 띕니다. 지금의 웅장한 바로크 건물은 주로 18세기에 세워졌지만, 수도원의 역사는 훨씬 오래되었습니다.\n\n수도원에는 책과 필사본을 보존해 온 도서관이 있습니다. 인쇄술이 널리 퍼지기 전 수도사들은 책을 손으로 베끼며 지식을 전했습니다. 천장에 화려한 그림이 그려진 도서관과 금빛 장식의 성당은 신앙과 예술이 어떻게 만나 왔는지를 보여줍니다. 멜크 수도원은 도나우강 유역의 역사와 배움의 전통을 함께 간직한 장소입니다.",
