      "aliases": [],
      "description": "바하우 계곡은 오스트리아의 도나우강이 산과 마을 사이를 굽이쳐 흐르는 아름다운 지역입니다. 강 양쪽에는 포도밭이 계단처럼 이어지고, 오래된 수도원과 성의 흔적, 작은 마을들이 자리합니다. 사람들은 가파른 비탈에도 돌담을 쌓고 밭을 가꾸며 오랜 세월 이 풍경을 만들어 왔습니다.\n\n바하우는 자연만 아름다운 곳이 아닙니다. 강을 따라 물건과 사람, 문화가 이동했고 포도 재배와 와인 생산도 이어졌습니다. 멜크 수도원과 뒤른슈타인 일대의 역사적인 건물은 그 시간을 보여줍니다. 자연과 사람이 함께 만든 문화경관의 가치가 인정되어 2000년 유네스코 세계유산에 등재되었습니다.",
