      "description": "프라하성(체코어: Pražský hrad 프라슈스키 흐라트)은 체코의 수도인 프라하에 블타바 강의 서쪽 언덕에 자리 잡고 있는 성으로 프라하의 초기 역사부터 존재해 왔으며 프라하의 상징이자 체코의 상징입니다. 체코의 왕들과 신성 로마 제국의 황제들이 이곳에서 통치를 했으며 현재는 체코 공화국의 대통령 관저가 이곳에 자리잡고 있습니다. 프라하 성은 기네스북에 따르면 세계에서 가장 큰 옛성입니다. 길이는 약 570 미터, 폭은 약 130 미터에 달합니다. 프라하 성은 체코의 주요 관광명소 중 하나로 매년 약 180만 명의 관광객이 찾고 있습니다.",
