      "aliases": [],
      "description": "카렐교(체코어: Karlův most)는 체코 프라하 블타바강 위에 있는 다리입니다. 신성 로마 제국의 황제이자 보헤미아 왕국의 국왕인 카를 4세의 통치 아래 1357년에 건설이 시작되어 1402년에 완성되었습니다. 1841년까지 프라하 구시가지와 프라하 성 쪽을 잇는 유일한 다리였습니다. 또한 서유럽 동유럽의 교역 루트로 프라하가 중요한 지위를 차지하게 되었습니다. 처음에는 단순히 돌다리(Kamenný most)라고 했지만 1870년부터 카렐교로 불리게 되었습니다. 1841년까지는 프라하에서 블타바 강을 가로지르는 유일한 다리였기 때문에, 프라하 성과 구시가지(스타레메스토)를 잇는 중요한 교통의 요지였습니다. 이러한 점 때문에 프라하는 서유럽과 동유럽을 잇는 주요 교역 루트로 발전할 수 있었다.",
