      "description": "프라하의 페트르진 전망탑은 도시 서쪽 언덕 위에 세워진 철제 탑입니다. 1891년 프라하에서 열린 산업박람회 무렵 세워졌으며, 파리 에펠탑에서 영감을 받은 형태로 잘 알려져 있습니다. 에펠탑보다 훨씬 작지만 높은 언덕 위에 서 있어 프라하의 빨간 지붕과 블타바강, 오래된 성곽을 넓게 조망할 수 있습니다. 탑 주변의 정원과 산책길은 계절마다 다른 모습을 보여 줍니다. 먼 나라의 유명한 건축물을 참고하면서도 자기 도시의 풍경에 어울리는 새로운 상징을 만들어 낸 사례입니다.",
