      "description": "바츨라프 광장(체코어: Václavské náměstí)은 체코 프라하 신시가지에 있는 광장입니다. 체코 역사의 많은 사건들이 발생한 역사적인 장소이며, 현재에도 시위, 축하행사 등이 많이 열린다. 광장 이름은 보헤미아의 수호 성인인 바츨라프 1세 공작에서 유래된 이름입니다. 프라하 역사지구의 중심이라 할 수 있습니다. 바츨라프 광장은 중세 시대에는 말 시장(Koňský trh)이었으나, 1848년 보헤미아의 시인 카렐 하블리체크 보로프스키(Karel Havlíček Borovský)의 제안으로 성 바츨라프 광장으로 명칭이 바뀌었다.",
