      "description": "체스키크룸로프 an der Moldau 크루마우안데어몰다우)는 체코 남보헤미아 주의 작은 도시입니다. 《크룸로프 성》을 포함한 뛰어난 건축물과 역사 문화재로 유명하며, 체스키크룸로프 구 시가지는 유네스코 세계유산입니다. 체스키는 체코어로 〈보헤미아의 것〉을 의미하며, 이것에 의해 모라비아에 있는 모라프스키크룸로프(Moravský Krumlov)와 구별된다. 크룸로프는 〈강의 만곡부의 습지〉를 의미하며, 독일어의 크루메 아우에(Krumme Aue)를 그 어원으로 합니다. 1920년 이전에는 〈크루마우안데어몰다우〉라는 명칭으로 알려졌으며, 오래된 옛 지도에는 크루마우(Krumau)라고 기재되어 있는 것이 많다.",
