      "description": "체코의 레드니체 성은 동화 속 궁전처럼 뾰족한 탑과 화려한 장식이 이어지는 성입니다. 이곳은 오랫동안 리히텐슈타인 가문의 영지였으며, 19세기에 지금과 같은 낭만적인 신고딕 양식으로 크게 바뀌었습니다. 성 안에는 정교한 나무 계단과 아름답게 꾸민 방들이 남아 있습니다.\n\n성 주변에는 드넓은 정원과 연못, 길이 이어지고 멀리 이국적인 모습의 미나레트도 세워졌습니다. 귀족들은 정원과 건물을 하나의 거대한 풍경처럼 설계했습니다. 가까운 발티체와 함께 이루는 레드니체–발티체 문화경관은 1996년 유네스코 세계유산으로 지정되었습니다. 성과 정원이 함께 하나의 작품이 된 곳입니다.",
