      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "벨렝탑(포르투갈어: Torre de Belém)은 포르투갈 리스본에 위치한 16세기 방어시설로, 포르투갈 탐험가들의 출항 및 입항 지점이자 리스본의 의례적인 관문 역할을 했습니다. 이 탑은 근대 초기 유럽에서 포르투갈의 해상 및 식민지 권력을 상징합니다. 포르투갈 르네상스의 전성기에 건축되었으며 포르투갈의 마누엘 양식을 보여주는 대표적인 건축물이지만, 무어 건축에서 영감을 받은 망대와 같은 다른 건축 양식들도 포함하고 있습니다. 이 구조물은 리스본 지역의 현지 재료인 석회암으로 건축되었으며, 보루 (건축)와 30m 높이의 4층 탑으로 구성되어 있습니다. 1983년부터 이 탑은 제로니무스 수도원과 함께 유네스코 세계유산으로 지정되었습니다. 랜드마크로서의 위상 덕분에 종종 유럽의 대항해 시대를 상징하거나 포르투갈 또는 리스본을 대신하는 대유법으로 사용된다.",
      "wikiTitle": "",
