      "description": "상조르즈성(포르투갈어: Castelo de São Jorge)은 포르투갈 리스본에 있는 성입니다. 기원전 2세기 지어진 것이 시초로 현재의 명칭은 포르투갈의 국왕인 주앙 1세의 명으로 성 게오르기우스를 기리기 위해 개칭했습니다. 성 일대는 성벽에 둘러싸인 사각형의 요새의 모습입니다. 왕궁 유적은 주요 문 근처에 있어, 일부 벽과 재건된 카사 오기발의 방이 남아있습니다. 가장 높은 요새 부분의 북서쪽에는 중세의 성이 있었다.",
