      "description": "코메르시우 광장(포르투갈어: Praça do Comércio)은 포르투갈 리스본의 광장입니다. 타구스강변에 위치해있으며 과거에 마누엘 1세의 리베이라 궁전이 위치해 있었기 때문에 궁전 광장이라는 별칭으로도 통합니다. 1755년 리스본 대지진으로 궁전이 파괴된 이후에 폼발 후작의 도시계획에 의해 광장으로 재건축되었습니다.",
