      "aliases": [],
      "description": "포르투갈 리스본의 알파마 지구는 언덕을 따라 작은 집과 좁은 골목이 이어지는 오래된 동네입니다. 자동차 한 대가 겨우 지나갈 듯한 길 사이로 계단과 골목길이 구불구불 연결되고, 노란색 전차가 경사진 거리를 오르내립니다. 이곳에는 리스본이 무역항으로 성장하기 전부터 이어져 온 도시의 흔적이 남아 있습니다.\n\n1755년 리스본에 큰 지진이 일어났을 때 알파마의 일부 구역은 다른 중심지보다 오래된 골목 구조를 더 많이 지켜 냈습니다. 알파마는 애절한 노래인 파두와도 깊은 인연이 있습니다. 저녁이면 좁은 거리에서 들려오는 노래와 오래된 집들이 리스본의 생활문화를 이어 갑니다.",
