      "description": "엘리베이터 또는 리프트 또는 승강기(昇降機, 문화어: 수직승강기)는 사람이나 화물을 여러 층 사이로 수직 이동시키는 기계입니다. 일반적으로 호이스트와 같은 권상 로프와 균형추 시스템을 구동하는 전동기에 의해 작동하지만, 일부는 잭과 같은 원통형 피스톤을 들어 올리기 위해 유압유를 펌핑하는 유압식으로 작동하기도 합니다. 엘리베이터는 농업 및 제조업에서 자재를 들어 올리는 데 사용되며, 광산 등에서 사용되기도 합니다. 체인 및 버킷 엘리베이터, 곡물 오거, 건초 엘리베이터 등 다양한 유형이 있습니다. 현대 건축물에서는 특히 경사로 설치가 불가능한 곳에서 접근성을 보장하기 위해 엘리베이터를 설치하는 경우가 많다. 마천루에는 고속 엘리베이터가 흔히 설치된다. 일부 엘리베이터는 수평으로 이동할 수도 있습니다.",
