      "description": "포르투의 동 루이스 1세 다리는 도루강 양쪽의 가파른 도시를 연결하는 거대한 철제 아치교입니다. 1886년에 완성된 이 다리는 프랑스 기술자 테오필 세이리그가 설계했으며, 그와 함께 일했던 귀스타브 에펠의 철교 기술 시대를 떠올리게 합니다. 특히 다리의 위층과 아래층이 서로 다른 높이의 길을 잇는 구조가 독특합니다. 오늘날 위쪽에는 도시철도가 지나고 아래쪽에는 차량과 보행자가 오갑니다. 강변의 오래된 건물과 높은 철교가 어우러지며 포르투를 대표하는 풍경을 만듭니다.",
