      "description": "포르투의 렐루 서점은 책을 파는 가게이면서도 건물 자체가 예술 작품처럼 알려진 곳입니다. 1906년 문을 연 이 서점에는 붉은빛을 띤 굽이치는 계단과 화려한 목조 장식, 색유리 천장이 어우러져 있습니다. 특히 계단은 가운데에서 갈라져 다시 이어지는 듯한 독특한 곡선으로 유명합니다. 오래된 서점이 이렇게 많은 사람의 관심을 받는 까닭은 책과 건축이 하나의 공간에서 특별한 분위기를 만들기 때문입니다. 해리 포터와 연결하는 이야기가 널리 퍼졌지만, 작가가 이 서점에서 영감을 얻었다는 주장은 확인된 사실로 보기는 어렵습니다.",
