      "aliases": [],
      "description": "포르투갈 포르투의 클레리구스 탑은 오래된 도심 위로 높이 솟은 바로크 양식의 종탑입니다. 18세기 건축가 니콜라우 나조니가 설계한 클레리구스 교회와 연결되어 있으며, 탑의 높이는 약 76미터입니다. 좁은 계단을 따라 올라가면 포르투의 붉은 지붕들과 도루강 주변의 풍경이 펼쳐집니다.\n\n과거 높은 종탑은 도시에서 시간을 알리고 멀리 떨어진 곳에서 위치를 확인하는 역할도 했습니다. 오늘날 클레리구스 탑은 포르투를 상징하는 건축물로 남아 있습니다. 화려한 돌 장식과 균형 잡힌 형태는 포르투갈 바로크 건축이 얼마나 섬세했는지를 보여줍니다.",
