      "description": "포르투갈 북부의 두루 계곡은 도루강을 따라 포도밭이 층층이 올라가는 특별한 풍경으로 유명합니다. 산비탈은 가파르지만 사람들은 돌담과 계단식 밭을 만들어 오랫동안 포도를 재배해 왔습니다. 이렇게 생산한 포도로 만든 와인은 강을 따라 배에 실려 포르투 쪽으로 운반되곤 했습니다.\n\n특히 두루 계곡은 포트 와인의 산지로 널리 알려져 있습니다. 강과 산, 포도밭, 작은 마을이 함께 이루는 모습은 단순한 자연경관이 아니라 여러 세대의 노동이 만든 문화경관입니다. 오래된 포도 재배 지역의 가치를 인정받아 알투 두루 와인 지역은 2001년 유네스코 세계유산으로 등재되었습니다.",
