      "name": "에보라 로마 신전",
      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "고대 로마 신전은 로마 문화의 고고학적 유물 가운데 가장 시각적이며, 로마 건축 이해에서 중요한 요소입니다. 신전(神殿) 만들고 유지하는 게 고대 로마 종교의 주요한 한 부분이었다. 켈라(cella)라고 불린 주실(主室)에 해당 신전이 모시는 신의 신상(神像)이 놓여 있었으며, 종종 향을 피우거나 제주(祭酒)를 올리는 작은 제단이 함께 놓여 있었다. 켈라 뒤에는 신전의 수행원들과 관리인들의 용품이나 봉헌자들의 봉헌물을 보관하는 용도로 사용한 하나 혹은 그 이상의 방이 있었다. 신전(神殿) 뜻하는 영어 단어 템플(temple)은 라틴어 템플룸(templum)에서 유래하였습니다. 본디 템플룸(templum)은 빌딩을 뜻하는 게 아니라 의식을 통해 측량하고 구획한 신성한 장소를 뜻하는 낱말이었다.",
