      "description": "크라쿠프 중앙광장은 폴란드 남부 옛 왕도 한가운데 펼쳐진 거대한 중세 광장입니다. 13세기 도시를 정비하면서 조성된 광장 주변에는 성 마리아 성당과 옛 직물회관이 자리합니다. 가운데 길게 놓인 직물회관은 상인들이 천과 여러 물건을 거래하던 상업의 중심지였습니다. 성 마리아 성당의 높은 탑에서는 시간을 알리는 나팔 소리가 울려 퍼지는데, 연주가 도중에 갑자기 끝나는 모습에 오래된 전설이 전해집니다. 커다란 광장 하나에 시장과 종교, 음악과 도시 생활의 역사가 함께 담겨 있습니다.",
