      "description": "바르샤바, 공식적으로 수도 바르샤바(Miasto stołeczne Warszawa)는 폴란드의 수도이자 최대 도시로 폴란드 중동부의 비스와강 연안에 위치합니다. 인구는 186만 명이며 대도시권을 포함하면 310만 명으로 유럽 연합 6위입니다. 18개 구로 이루어져 있으며 면적은 517km²이고 대도시권을 포함하면 6,100km²입니다. 세계도시이자 문화, 정치, 경제, 교통의 중심지이며 정부 소재지입니다. 바르샤바의 기원은 마조프셰의 작은 어촌으로 거슬러 올라간다. 16세기 후반 지그문트 3세는 수도와 궁정을 크라쿠프에서 바르샤바로 옮겼고 바르샤바는 1795년까지 폴란드-리투아니아 공화국의 사실상 수도였습니다. 이후 나폴레옹은 이곳에 바르샤바 공국을 세웠다. 19세기와 산업혁명으로 인하여 인구가 폭증했고 그 결과 유럽에서 가장 크고 인구 밀도가 높은 도시 중 하나가 되었습니다.",
