      "description": "토룬은 폴란드 비스와강가에 자리한 중세 도시로, 오래된 붉은 벽돌 건물이 모여 있는 구시가지가 유명합니다. 한때 무역도시로 번성하며 성벽과 교회, 상인들의 집이 세워졌고, 여러 건물이 오늘날까지 이어졌습니다. 지구가 태양 주위를 돈다는 생각을 발전시킨 천문학자 니콜라우스 코페르니쿠스가 태어난 도시로도 알려져 있습니다. 이 지역의 전통 과자인 진저브레드 역시 토룬의 오랜 자랑거리입니다. 상업과 과학, 음식의 역사가 한 도시의 좁은 골목 안에 함께 남아 있습니다.",
