      "aliases": [],
      "description": "브로츠와프는 폴란드의 남서부 실레시아 지방에 있는 돌니실롱스크주의 주도입니다. 오데르강(Odra, 오드라 강)이 도시의 중앙을 관통하여 남동쪽에서 북서쪽으로 흐른다. 인구는 2017년 기준으로 637,683명입니다. 브로츠와프는 폴란드에서 가장 유명한 도시 중 하나이며, 큰 대학과 국제 학교, 성당 섬, 수많은 역사적 기념물 및 다채로운 시장 광장이 있습니다. 광장은 유럽에서 가장 아름다운 곳 중 하나입니다. 주요 관광 명소는 도시 전체에 흩어져있는 작은 난쟁이 상으로, 2019년 기준으로 약 300개의 난쟁이가 있습니다. 브로츠와프의 시청은 또한 유명한 랜드마크입니다. 그것은 13세기와 16세기 사이에 지어졌다.",
