      "description": "폴란드 포즈난의 구시가지는 알록달록한 건물들이 광장을 둘러싼 역사적인 중심지입니다. 한가운데에는 르네상스 양식으로 꾸민 시청사가 있고, 시청사 시계 위에서는 매일 정해진 시간에 작은 염소 두 마리가 나타나 뿔을 맞부딪치는 장면을 연출합니다. 이 독특한 전통은 도시를 대표하는 이야기가 되었습니다.\n\n전설에 따르면 잔치에 쓰려던 염소들이 도망쳐 시청사 탑에 올라가 서로 부딪쳤다고 합니다. 실제 역사와 전설은 구분해야 하지만, 염소 이야기는 포즈난 사람들의 사랑을 받습니다. 오래된 광장에는 상인들의 집과 시장의 흔적도 남아 있어 도시의 오랜 상업 역사를 전합니다.",
