      "description": "타트라 국립공원(폴란드어: Tatrzański Park Narodowy, 약칭 TPN)은 폴란드 중남부 마워폴스카주 타트라군의 타트리산맥에 위치한 국립공원입니다. 타트리산맥은 북쪽의 폴란드와 남쪽의 슬로바키아 사이의 천연 국경을 형성하며, 두 나라는 20세기 초부터 이 지역을 보호하기 위해 협력해 왔다. 슬로바키아는 인접한 국립공원을 조성했으며, 유네스코는 나중에 이 지역을 접경 생물권보전지역으로 지정했습니다. TPN의 출입 가능 구역에서는 하이킹, 스크램블링, 등반, 빙벽 등반 및 스키를 즐길 수 있습니다.",
