      "aliases": [],
      "description": "폴란드 쳉스토호바의 야스나구라 수도원은 오랫동안 많은 순례자가 찾는 가톨릭 성지입니다. 수도원에는 '쳉스토호바의 검은 성모'라고 불리는 성모 마리아의 성화가 보존되어 있습니다. 오랜 세월 기도와 순례의 중심이 되어 왔으며, 폴란드의 역사와 정체성에서도 특별한 의미를 지닙니다.\n\n17세기 스웨덴군이 폴란드를 침공했을 때 수도원이 포위 공격을 견뎌 낸 사건은 나라를 지키려는 저항의 상징으로 전해졌습니다. 오늘날에도 사람들은 여러 도시에서 먼 길을 걸어 이곳을 찾습니다. 야스나구라는 종교 건축물인 동시에 폴란드 사람들이 역사 속에서 희망을 모았던 장소입니다.",
