      "description": "모르스키에오코호는 폴란드 고타트리산맥에 위치한 작은 호수로 면적은 34.93ha, 최대 길이는 862m, 최대 너비는 566m이며 최대 수심은 50.8m, 수면 높이는 1,395m입니다. 호수 이름은 폴란드어로 \"바다의 눈\"을 뜻합니다. 타트리산맥에서 큰 호수이자 4번째로 깊은 호수로서 폴란드 마워폴스카주에 위치합니다. 높이가 1,000m를 넘는 산들에 둘러싸여 있는데 리시산(Rysy, 높이 2,499m)은 폴란드령 타트리산맥에서 가장 높은 산입니다. 호수 주변에는 스위스소나무가 서식하고 있습니다. 타트리산맥에 위치한 호수와 연못에서는 드물게 많은 물고기가 서식하기 때문에 \"물고기의 호수\"(폴란드어: Rybie Jezioro 리비에 예지오로)라는 별칭으로 부르기도 합니다. 호수 북쪽에 위치한 빙퇴석 지형에는 폴란드 관광 민간 전승 협회(PTTK)에서 설치한 오두막이 있습니다.",
