      "aliases": [],
      "description": "흐바르(크로아티아어: Hvar, 이탈리아어: Lesina 레시나)는 크로아티아 스플리트달마티아주의 흐바르섬에 위치한 도시로 면적은 75.5km2, 인구는 4,251명(2011년 기준), 인구 밀도는 55명/km2입니다. 13세기부터 18세기까지 베네치아 공화국의 지배를 받으면서 요새, 성곽, 해군 기지가 건립되었으며 아드리아해의 문화, 교역의 중심지로 여겨졌다. 15세기부터 17세기 사이에는 귀족이 소유한 주택, 관공서가 건립되었고 1612년에는 유럽에서 오래된 극장이 건립되었을 정도로 문화 분야에서 크게 발전했습니다. 아드리아해와 접한 자연항인 흐바르 항은 흐바르섬 남쪽에 위치한 파클레니 제도를 보호하는 역할을 담당하고 있기 때문에 이 곳을 오가는 수많은 선박들이 안전하게 항해할 수 있도록 도와준다.",
