      "description": "자그레브 대성당은 크로아티아 수도 자그레브의 중심부에 있는 가톨릭 성당입니다. 중세부터 이곳에 성당이 있었고, 13세기에 몽골군 침입으로 훼손된 뒤 다시 세워졌습니다. 지금 보이는 높은 첨탑과 고딕 양식의 모습은 1880년 대지진 이후 복원 과정과 깊이 연결됩니다. 2020년 지진으로 또 큰 피해를 입어 보수 작업이 이어졌습니다. 성당을 살펴볼 때에는 하늘을 향해 솟은 첨탑과 벽면의 섬세한 창문을 눈여겨보세요. 한 건축물이 여러 세대의 역사와 재난을 견디며 이어졌다는 사실이 흥미롭습니다.",
