      "aliases": [],
      "description": "네뢰위 피오르(Nærøyfjord)는 노르웨이 베스틀란주 아울란에 있는 피오르입니다. 이 좁은 피오르는 거대한 송네 피오르의 지류입니다. 길이 18-킬로미터 (11 mi)의 이 피오르는 일부 구간의 너비가 500 미터 (1,600 ft)에 불과하다. 네뢰이다셀비강은 유럽 고속도로 16호선 인근의 구드방엔 마을에서 네뢰이다렌 계곡을 따라 피오르로 흘러든다. 바카 마을과 바카 교회는 모두 피오르의 서쪽 해안에 위치해 있습니다. 2005년부터 네뢰이 피오르는 유네스코 세계유산으로 등재되었습니다. 또한 내셔널 지오그래픽 협회에 의해 게이랑에르 피오르와 함께 세계 최고의 자연 유산지로 선정되기도 했습니다. 네뢰위 피오르를 포함한 노르웨이 서부 피오르는 국제적으로 문화유산보다는 주로 '자연/경관 유산'지로 소개되고 인식된다.",
