      "description": "브뤼겐(노르웨이어: Bryggen, 부두)은 튀스케브뤼겐(노르웨이어: Tyskebryggen, 독일 부두)으로도 알려져 있으며, 노르웨이 베르겐의 보겐항 동쪽을 따라 늘어선 일련의 한자동맹 유산 상업 건물군입니다. 브뤼겐은 1979년부터 유네스코 세계유산 목록에 등재되어 있습니다. 베르겐시는 1070년경 튀스케브뤼겐의 경계 내에서 건립되었습니다. 1350년경 이곳에 한자동맹의 콘토어(Kontor)가 설치되었으며, 튀스케브뤼겐은 노르웨이 내 한자 상업 활동의 중심지가 되었습니다. 오늘날 브뤼겐에는 박물관, 상점, 식당 및 술집이 들어서 있습니다.",
