      "aliases": [],
      "description": "레이네는 노르웨이 북쪽 로포텐 제도에 자리한 작은 어촌 마을입니다. 날카로운 산봉우리와 깊은 바다가 가까이 맞닿아 있고, 해안에는 붉은색 어부 오두막인 '로르부'가 줄지어 있습니다. 이 오두막은 원래 먼 곳에서 고기잡이를 하러 온 어부들이 머물던 숙소였습니다. 북대서양의 대구잡이는 오랫동안 이 지역 사람들의 삶과 경제를 지탱했습니다. 겨울에는 눈 덮인 산과 어촌이 어우러지고, 여름에는 밤에도 해가 완전히 지지 않는 백야가 찾아옵니다. 작지만 바다와 계절의 변화가 뚜렷한 마을입니다.",
