      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "대성당은 교구 전체의 중심이 되는 기독교의 성당을 일컫는 말이며, 교구의 관리자인 교구장주교의 주교좌가 있기 때문에 주교좌성당(主敎座聖堂, 라틴어: Ecclesia Cathedralis)이라고도 합니다. \"대성당\"의 기능을 가진 교회는 일반적으로 로마 가톨릭교회, 동방 정교회, 성공회 및 일부 루터교회와 같이 주교 계층을 가진 기독교 교단에 특화되어 있습니다. 대성당의 기능을 구현하는 교회 건물은 4세기에 이탈리아, 갈리아, 스페인, 북아프리카에서 처음 나타났지만, 서방 로마 가톨릭교회에서 대성당이 보편화된 것은 12세기가 되어서였습니다. 이때 대성당은 사목구 성당, 수도원 교회, 주교 거주지와는 다른 건축 양식, 제도적 구조 및 법적 정체성을 발전시켰다. 대성당은 주교가 자신의 행정 권한 아래 있는 지역을 통치하는 곳이기 때문에 교회보다 계층상 더 중요하다.",
