      "description": "노르웨이 북쪽의 트롬쇠 케이블카는 도시 건너편 산의 높은 전망대로 올라갑니다. 트롬쇠는 북극권 안에 있어 여름에는 밤에도 해가 완전히 지지 않는 백야를, 겨울에는 긴 어둠과 오로라를 경험할 수 있는 곳입니다. 같은 산에서도 계절에 따라 하늘의 모습이 놀랍게 달라집니다.\n\n케이블카가 오르는 스토르스테이넨 전망대에서는 섬 위의 도시와 주변의 뾰족한 산, 바다로 이어지는 해협이 펼쳐집니다. 트롬쇠는 오래전부터 북극 지역 탐험과 연구의 출발점이었습니다. 산 위에서 바라보는 도시의 불빛은 먼 북쪽에서도 사람들이 활기차게 살아가는 모습을 보여줍니다.",
