      "description": "오슬로 오페라 하우스는 노르웨이 국립 오페라 앤 발레단과 노르웨이 국립 오페라 극장의 본거지입니다. 이 건물은 오슬로피요르드 상부의 오슬로 중부에 이웃한 비요르비카에 위치해 있습니다. 노르웨이 정부의 재산을 관리하는 정부 기관인 Statsbygg에 의해 운영되고 있습니다. 이 구조물은 38,500 m2의 총 면적에 1,100개의 방이 있습니다. 주 강당 좌석수는 1,364개이며 다른 공연 공간 좌석수는 200~400개입니다. 주 무대는 16미터 너비, 40미터 높이입니다.",
