      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "노르웨이 오슬로의 비겔란 조각공원에는 사람의 삶을 주제로 한 수많은 조각이 모여 있습니다. 조각가 구스타브 비겔란은 태어남과 성장, 사랑과 갈등, 나이 듦 같은 인간의 여러 모습을 작품으로 표현했습니다. 공원 한가운데 솟은 '모놀리스'에는 여러 인체 형상이 돌기둥을 따라 빽빽하게 조각되어 있습니다.\n\n가장 유명한 작품 가운데 하나는 화가 난 작은 아이를 표현한 '성난 아이'입니다. 동작과 표정만으로 감정을 드러내는 조각이어서 많은 사람의 기억에 남습니다. 이 공원은 조각을 실내 박물관이 아닌 넓은 산책 공간 속에 배치해 예술과 일상이 자연스럽게 만나도록 했습니다.",
