      "description": "뭉크 미술관(노르웨이어: Munch-museet)은 노르웨이 예술가 에드바르 뭉크의 생애와 작품에 헌정된 노르웨이 오슬로 비요르비카에 있는 미술관입니다. 이 미술관은 원래 1963년 퇴옌에서 개관했습니다. 2021년 10월 22일에 비요르비카에 건립된 새 건물로 이전했습니다.",
