      "name": "아케르스후스 요새",
      "category": "heritage",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "노르웨이 오슬로 항구 옆의 아케르스후스 요새는 중세부터 수도를 지켜 온 성과 방어시설입니다. 13세기 말에 건설이 시작되었고, 여러 왕과 통치자가 성벽과 건물을 고치면서 시대에 맞게 확장했습니다. 항구를 내려다보는 높은 위치 덕분에 바다에서 접근하는 적을 감시하기 좋았습니다.\n\n요새는 왕의 거처이자 군사기지, 때로는 감옥으로도 사용되었습니다. 오늘날에는 성곽과 박물관, 기념시설을 통해 오슬로가 겪어 온 역사를 전합니다. 바다 가까이 우뚝 선 두꺼운 돌담은 화려한 궁전과는 또 다른 북유럽의 중세 모습을 보여줍니다.",
