      "description": "노르카프(노르웨이어: Nordkapp)는 노르웨이의 핀마르크주에 위치한 노르웨이에서 가장 북쪽에 위치한 지역입니다. 노르카프는 노르웨이어로 \"북쪽의 곶\"을 뜻합니다. 또한 이 지역은 가장 북쪽에 있다는 이유로 여름철에는 백야가, 겨울철에는 극야가 일어나는 유명한 지역입니다. 그러나 하지 때에는 다른 노르웨이 도시 지역에서도 지평선 아래로 내려가지 않은 백야를 볼 수 있습니다. 하지만 이보다 조금 더 북쪽에 위치한 크니브셸로덴이라는 지역이 있습니다.",
