      "description": "요스테달스브레엔은 노르웨이 서부 산악지대에 펼쳐진 거대한 빙하입니다. 유럽 대륙에서 손꼽히는 큰 빙하로, 높은 산지에 쌓인 눈이 오랜 세월 눌리고 단단해지며 형성되었습니다. 빙하는 멈춰 있는 얼음덩어리처럼 보이지만 아주 천천히 아래쪽으로 흐르며 바위를 깎고 골짜기를 만듭니다.\n\n빙하에서 갈라져 나온 여러 빙하 혀는 깊은 계곡 쪽으로 뻗어 있습니다. 얼음이 녹아 흐르는 물은 강과 호수를 만들고, 암석 가루가 섞이면 물빛이 독특하게 보이기도 합니다. 빙하의 크기와 모습은 기후에 따라 변하기 때문에 요스테달스브레엔은 지구의 환경 변화를 이해하는 데에도 중요한 장소입니다.",
