      "description": "감라스탄(스웨덴어: Gamla stan)은 스웨덴의 수도인 스톡홀름의 구 시가지입니다. 감라스탄은 스웨덴어로 \"옛 도시\"를 뜻합니다. 감라스탄은 스타스홀멘 섬(Stadsholmen)에 위치하며 다리 사이에 위치한 거리를 뜻하는 \"스타덴 멜란 브로아르나\"(Staden mellan broarna)라고 부르기도 합니다. 감라스탄 주변에 있는 작은 섬들로는 리다르홀멘 섬(Riddarholmen), 헬게안스홀멘 섬(Helgeandsholmen), 스트룀스보리 섬(Strömsborg)이 있습니다. 감라스탄은 13세기부터 형성되었으며 중세 시대에 건설된 도로와 거리, 오랜 역사를 가진 건축물들이 들어서 있습니다. 감라스탄 중심부에 위치한 스토르토리에트 광장(Stortorget, 대광장)에는 스톡홀름 증권 거래소를 비롯한 옛 건축물들이 있습니다.",
