      "description": "스톡홀름 시청사(스웨덴어: Stockholms stadshus)는 스웨덴 스톡홀름의 시청 건물입니다. 노벨상 기념 만찬이 열리는 장소로 널리 알려져 있습니다. 스톡홀름 시의회는 1907년에 엘드크바른(Eldkvarn)이 있던 곳에 새로운 시청사를 짓기로 결정했습니다. 엘드크바른은 1878년에 일어난 화재로 인해 사라진 곡물 제분소입니다. 그 뒤 건축 설계 공모전이 진행되었고 스웨덴의 건축가인 랑나르 외스트베리(Ragnar Östberg), 칼 베스트만(Carl Westman), 이바르 텡봄(Ivar Tengbom), 에른스트 토룰프(Ernst Torulf), 칼 베리스텐(Carl Bergsten)이 공동으로 초안을 제출했습니다. 스톡홀름 시청은 베스트만과 외스트베리 간의 추가 경쟁을 통해 베스트만은 스톡홀름 법원 청사를, 외스트베리는 스톡홀름 시청사를 설계하기로 각각 결정했습니다.",
