      "description": "스웨덴 웁살라 성은 높은 언덕 위에서 오래된 대학도시를 내려다보는 왕실 건물입니다. 16세기 구스타브 바사 왕 때부터 건설되었고, 이후 여러 차례 화재와 보수, 증축을 겪었습니다. 성벽과 건물의 모습에는 스웨덴 왕국의 정치와 방어의 역사가 남아 있습니다.\n\n웁살라는 오랫동안 종교와 학문의 중심지였으며, 웅장한 웁살라 대성당과 유서 깊은 대학으로도 유명합니다. 성은 이러한 도시의 역사와 가까이 이어져 있습니다. 오늘날에는 문화시설과 전시공간으로 이용되며, 언덕 위에서 펼쳐지는 도시 풍경은 웁살라가 지닌 여러 시대의 모습을 한꺼번에 보여줍니다.",
