      "description": "비스뷔(Visby)는 스웨덴 고틀란드주의 주도입니다. 이곳은 잘 보존된 중세 도시이며 세계유산으로 지명된 상태입니다. 가장 유명한 역사적인 유물은 링무렌이라 불리는 3.4 km 길이의 돌벽이며, 도시와 오래된 교회 옛터를 에워싼다. 그 이름 \"비스뷔 (Visby)\"는 희생적인 장소를 뜻하는 (Vi의 속격 단수) 고대 노르드어 Vis와 \"도시\"를 뜻하는 by로부터 왔다. 도시의 인구는 22,236명(2005년 기준)이며, 고틀란드주의 주지사 소재지입니다. 스웨덴에 있는 다른 마을들과 도시들처럼, 비스뷔는 정치적이거나 행정적인 실체가 아니다. 고틀란드 자치제의 없어서는 안될 부분을 형성하며, 자치제의 소재지입니다.",
