      "description": "스웨덴 남동쪽의 칼마르 성은 바다와 가까운 물가에 자리한 오래된 요새입니다. 중세에 시작된 성은 16세기 바사 왕조 시기에 르네상스 양식으로 꾸며지면서 오늘날의 웅장한 모습이 되었습니다. 두꺼운 성벽과 둥근 탑, 물로 둘러싸인 방어시설에는 바다를 지키려던 노력이 남아 있습니다.\n\n1397년에는 스칸디나비아 세 왕국을 하나의 군주 아래 묶은 칼마르 연합이 이 도시에서 성립했습니다. 그 역사적인 이름 덕분에 칼마르는 북유럽 여러 나라의 관계를 설명할 때 빠지지 않는 곳입니다. 성 내부의 화려한 방과 외부의 거친 성벽은 왕실 생활과 군사적 긴장을 함께 전합니다.",
