      "aliases": [],
      "description": "예테보리(스웨덴어: Göteborg 듣기 )는 스웨덴에 있는 도시로 베스트라예탈란드주의 주도입니다. 인구는 581,822명(2018년 기준)으로 수도 스톡홀름에 이어 스웨덴에서 두 번째로 큰 도시입니다. 도시 이름은 스웨덴어로 \"고트인의 도시\"를 뜻합니다. 스웨덴 남서부, 예타강의 하구에 있는 항구 도시로, 예타강과 예타 운하를 비롯한 여러 개의 운하로 동부의 스톡홀름과 연결된다. 1619년 구스타브 2세 아돌프 국왕이 설립하였고, 상업과 노르웨이, 덴마크, 독일과 연결되는 해상 교통의 중심지로 발달하였습니다. 주요 산업은 식품 가공, 자동차, 섬유 공업이고, 예테보리 대학교의 소재지입니다. 예테보리의 주요 관광지로는 예테보리 해상 박물관, 놀이공원 리세베리(Liseberg) 등이 있습니다.",
