      "aliases": [],
      "description": "외레순 다리(덴마크어: Øresundsbroen, 스웨덴어: Öresundsbron, 양국 공통: Øresundsbron)는 외레순 해협에 걸친 도로·철도 병용교입니다. 바로 이어지는 드로그덴 터널과 함께 덴마크 코펜하겐과 스웨덴 말뫼를 잇는다. 도로 부분은 유럽 고속도로 20호선, 철도 부분은 외레순 선의 일부입니다. 유럽의 도로·철도 병용교로서는 가장 길다. 코펜하겐 공항을 드나드는 비행기와 간섭하지 않도록 하기 위해서 코펜하겐 쪽은 인공 섬인 페베르홀름(덴마크어: Peberholm→후추 섬)을 경유하여 해저 터널로 지난다. 다리 중간으로 국경선이 지나지만, 솅겐 조약 때문에 국경 통과 절차는 없다. 스웨덴 쪽에서는 세관 검사가 이따금씩 있지만, 덴마크 쪽은 없다.",
