      "description": "스웨덴 북부 유카스야르비의 아이스호텔은 겨울마다 얼음과 눈으로 특별한 공간을 만드는 곳입니다. 인근 강에서 얻은 얼음을 재료로 삼아 침실과 복도, 얼음 조각을 만들고, 여러 예술가가 서로 다른 모습의 방을 꾸밉니다. 계절이 바뀌면 일부 시설은 녹아 사라지고 다시 새롭게 만들어집니다. 영원히 남는 건물이 아니라 계절과 함께 태어나고 사라지는 예술이라는 점이 가장 독특합니다.",
