      "aliases": [],
      "description": "《인어공주》(人魚公主, 덴마크어: Den lille havfrue)는 덴마크의 작가 한스 크리스티안 안데르센이 저술한 동화입니다. 1837년 어린이를 위한 동화집의 일부로 최초 출간되었으며, 이야기는 인간의 영혼을 얻기 위해 인어로서의 바다 생활을 포기할 각오가 된 어린 공주 인어의 여정을 따라간다. 원작은 야콥 뵈길드와 페르닐레 헤가드 같은 학자들과 민속학자 마리아 타타르 등에 의해 여러 차례 분석되었습니다. 이러한 분석들은 이야기의 주제 해석부터 안데르센이 행복한 결말의 비극적 이야기를 쓰기로 결정한 이유에 대한 논의까지 다양한 측면을 다루고 있습니다. 이 작품은 뮤지컬 극장, 애니메이션, 발레, 오페라, 영화 등 다양한 매체로 각색되었습니다. 또한 이 이야기가 쓰이고 처음 출판된 덴마크의 코펜하겐에는 인어를 묘사한 동상이 있습니다.",
