      "description": "아말리엔보르 궁전은 덴마크 코펜하겐에서 왕실과 관련된 중요한 궁전입니다. 넓은 팔각형 광장을 사이에 두고 비슷한 모습의 네 궁전 건물이 마주 보고 있으며, 한가운데에는 프레데리크 5세의 기마상이 서 있습니다. 원래 귀족들의 저택으로 지어졌지만 18세기 말 큰 화재로 기존 왕궁이 손상된 뒤 왕실 거처가 되었습니다. 궁전 앞에서는 전통 제복을 입은 왕실 근위병을 볼 수 있습니다. 하나의 거대한 건물 대신 네 개의 궁전이 광장을 감싼 구조는 덴마크 왕실의 역사와 도시 계획을 함께 보여 줍니다.",
