      "aliases": [],
      "description": "로센보르성(덴마크어: Rosenborg Slot)은 덴마크 코펜하겐에 있는 르네상스 건축 양식의 성입니다. 1606년 덴마크의 크리스티안 4세 국왕에 의해 여름 궁전으로 건설되었으며 1624년에 준공되었습니다. 덴마크의 건축가인 베르텔 랑에(Bertel Lange), 한스 판 스테인빙컬(Hans van Steenwinckel)이 로센보르성의 건축 계획을 수립했습니다. 1710년에는 덴마크의 섭정에 의해 덴마크의 왕실 관저로 사용되었습니다. 프레데리크 4세 이후에 로센보르성이 왕실의 덴마크 왕실의 관저로 사용된 것은 1794년 크리스티안스보르 성 화재, 1801년 코펜하겐 해전으로 인한 비상 상황 뿐입니다. 로센보르성은 현재 국가 소유 재산으로 남아 있으며 1838년에는 일반에 개방되었습니다.",
