      "region": "",
      "aliases": [],
      "description": "코펜하겐은 덴마크의 수도이자 가장 인구가 많은 도시로 도시 지역에 약 140만 명의 인구가 있고, 코펜하겐 광역권에 200만 명이 넘는 인구가 있습니다. 이 도시는 외레순 해협을 사이에 두고 스웨덴의 말뫼와 분리된 셸란섬과 아마게르섬에 있습니다. 외레순 다리는 두 도시를 철도와 도로로 연결합니다. 현재 가멜 스탄 근처에 10세기에 형성된 원래 바이킹 어촌 마을인 코펜하겐은 15세기 초에 덴마크의 수도가 되었습니다. 17세기부터 이곳은 기관, 방어 시설, 군대와 함께 지역 권력의 중심지로서의 입지를 공고히 했습니다. 르네상스 시대에 이 도시는 칼마르 연합의 사실상의 수도 역할을 했으며 군주제의 소재지였으며, 국가 원수인 덴마크 군주가 통치하는 스웨덴과 노르웨이와의 개인 연합으로 오늘날 북유럽 지역의 대부분을 통치했습니다.",
