      "aliases": [],
      "description": "덴마크의 루이지애나 현대미술관은 바다를 향한 정원 속에 전시실이 이어지는 독특한 미술관입니다. 코펜하겐 북쪽 훔레베크에 자리하며, 1958년에 문을 열었습니다. 큰 건물 하나에 작품을 모으기보다는 여러 전시 공간을 유리 복도로 연결해 자연과 예술을 함께 느끼도록 설계했습니다.\n\n잔디밭에는 조각 작품이 놓이고, 창밖으로는 외레순 해협의 바다가 펼쳐집니다. 이름 때문에 미국의 루이지애나주와 관련된 곳으로 오해하기 쉽지만, 미술관 이름은 원래 이 자리에 있던 별장에서 이어졌습니다. 주변 풍경 자체가 전시 경험의 일부가 되는 미술관입니다.",
