      "description": "프레데릭스보르성(덴마크어: Frederiksborg Slot)은 덴마크 힐레뢰드에 있는 성입니다. 스칸디나비아에서 가장 큰 르네상스 건축 양식의 성입니다. 프레데릭스보르성 안에는 덴마크 국립역사박물관, 예배당, 대형 홀, 프레데릭스보르성 공원이 들어서 있습니다. 1560년 프레데리크 2세 국왕에 의해 건설되었으며 궁전의 이름 또한 여기서 유래된 이름입니다. 1601년부터 1620년까지 크리스티안 4세 국왕의 명령을 받은 건축가인 한스 반 스테인빙컬(Hans van Steenwinckel), 로렌츠 판 스테인빙컬(Lorenz van Steenwinckel)에 의해 현재와 같은 성이 건설되었습니다. 네덜란드의 건축 양식을 선호했던 크리스티안 4세 국왕은 코펜하겐에 지어진 새 건축물에도 이와 같은 양식을 도입했습니다.",
