      "name": "바이킹 선박 박물관",
      "category": "nature",
      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "바이킹은 노르드어 비킹(고대 노르드어: Vikingr)에서 유래한 표현입니다. 북게르만족 노르드인이고, 노르드어를 사용하며, 고향 땅인 스칸디나비아로부터 8세기 말에서 11세기 말까지 북유럽과 중앙유럽까지 항해하며 교역하거나 약탈로 활보한 바닷사람을 가리켜 바이킹이라고 부른다. 바이킹이 활동한 시기를 바이킹 시대라고 합니다. 노르드인들의 군사적 상업적 성장과 인구 팽창은 중세 스칸디나비아 뿐만 아니라 브리튼 제도, 아일랜드섬, 프랑스, 키예프 루스, 시칠리아 등 광범한 지역에 중요한 요소로 영향을 미쳤다. 롱쉽으로 대표되는 진보한 항해 기술로 인하여, 본거지인 스칸디나비아에서 멀리 떨어진 지중해 연안, 북아프리카, 중동, 중앙아시아까지 바이킹의 활동이 미친 적도 있었다. 바다와 강을 통한 탐험과 식민의 시기가 지난 뒤 바이킹들은 북서유럽, 동유럽, 북대서양 도서, 멀리는 북아메리카 북동해안에 이르기까지 각지에 정착했습니다.",
