      "description": "덴마크 에스비에르 해안의 '사람과 바다'는 네 명의 거대한 흰색 인물이 나란히 앉아 바다를 바라보는 야외 조각입니다. 조각가 스벤 비그 한센이 만든 작품으로, 단순한 얼굴과 자세 때문에 멀리서도 알아보기 쉽습니다. 앉아 있는 인물들은 잔잔한 바다와 넓은 하늘을 배경으로 더욱 크게 느껴집니다.\n\n에스비에르는 북해의 항구도시로 성장해 왔습니다. 바다를 향해 앉은 인물들은 인간과 자연, 항구도시의 관계를 떠올리게 합니다. 복잡한 장식이 없는 단순한 형태만으로도 강렬한 인상을 남기는 것이 이 작품의 특별한 점입니다.",
