      "description": "덴마크 묀섬의 묀스 클린트는 발트해를 따라 길게 이어지는 눈부신 흰 절벽입니다. 절벽을 이루는 하얀 분필 같은 암석은 아주 오래전 바다에 살던 미세한 생물의 껍데기가 쌓여 만들어졌습니다. 빙하기의 얼음이 지층을 밀어 올리고 이후 파도가 깎으면서 지금의 가파른 해안이 형성되었습니다. 절벽 아래에는 오래된 바다 생물의 화석도 발견됩니다. 하얀 절벽에 지구의 먼 과거가 새겨져 있는 셈입니다.",
