      "description": "우스펜스키 대성당(핀란드어: Uspenskin katedraali; 스웨덴어: Uspenskijkatedralen)은 핀란드 헬싱키에 있는 핀란드 정교회 주교좌 성당입니다. 수호성인은 성모 마리아(성모 안식)입니다. 대성당의 이름은 고대 교회 슬라브어로 성모 안식을 의미하는 ‘우스페니에’(uspenie)라는 단어에서 유래했습니다. 설계는 러시아 건축가 알렉세이 고르노스타예프(1808–1862)가 맡았으나 대성당 공사는 그의 사후 1862년에 시작돼 1868년에 완공됐다. 대성당 지하에는 1914년부터 1917년까지 헬싱키 정교회 본당 주교 대리로 봉사했으며 사후 시성된 알렉산데르 호토비츠키의 이름을 딴 경당이 있습니다. 대성당은 시내가 내려다 보이는 카타나야노카 반도의 언덕 위에 자리잡고 있습니다.",
