      "description": "도서관은 책, 잡지, 영상 매체, 마이크로필름 등의 다양한 자료를 공공 기관, 단체나 개인이 수집·정리하여 민간 또는 특정 사용자들이 열람하고 대출할 수 있도록 한 시설이자 문화 및 정보의 중심지다. 도서를 비롯한 각종 정보 자료를 수집, 정리 및 보존함으로써 교육 체계와 정보의 축적, 검색에 매우 중요한 역할을 하며 독서, 조사, 연구에 이용될 수 있습니다. 도서관 이용자는 도서관에 있는 매체를 통해 여러 세대에 걸쳐 축적된 지식을 열람할 수 있습니다. 또한 교육·업무·여가 선용에도 중요한 역할을 합니다. 도서관의 종류에는 국가가 운영하는 국립 도서관, 지역 사회 주민들이 이용하는 공공 도서관, 대학 도서관, 초·중·고등학교의 학교 도서관, 개인·협회·기업·정부 기관의 요구에 따라 필요한 정보를 수집해서 제공하는 전문·특수 도서관이 있습니다.",
