      "description": "오줌싸개 소년(네덜란드어: Manneken Pis 마네컨 피스)은 벨기에 브뤼셀 중심부에 위치한 상징적인 55.5 cm (21.9 in) 청동 분수 조각상으로, 소변을 보는 어린이, 즉 분수대에 오줌을 누는 나체의 어린 소년의 모습을 묘사합니다. 15세기 중반부터 그 존재가 확인되었지만, 오줌싸개 소년은 브라반트 공국의 조각가 제롬 뒤케누아가 재설계하여 1619년에 설치되었습니다. 프티 그라니트로 만들어진 로카유 양식의 벽감은 1770년에 만들어졌다. 이 조각상은 역사상 여러 차례 도난당하거나 훼손되었습니다. 1965년 이후로는 복제품이 현장에 전시되고 있으며, 원본은 브뤼셀 시립 박물관에 보관되어 있습니다. 오줌싸개 소년은 브뤼셀과 벨기에를 대표하는 상징 중 하나이며, 여러 전설뿐만 아니라 국내외에서 수많은 모방작과 유사한 조각상에 영감을 주었다.",
