      "description": "파슈파티나트 사원(네팔어: पशुपतिनाथ मन्दिर)은 네팔의 수도인 카트만두 동쪽 바그마티 강변에 있는 힌두 사원입니다. 세계에서도 가장 신성한 시바신의 사원이어서 매일 세계 각지에서 온 수천의 힌두신자들이 찾고 있으며, \"시바라티\" 또는 '시바신의 밤'이라고 불리는 의식 때는 수 만명의 순례자들이 이곳을 찾는다. 파슈파티나트 사원은 네팔 주민에게도 종교적으로나 문화적으로 일상생활의 중요한 부분이라고 할 수 있습니다. 수 천의 주민이 이곳을 방문하여 시바신으로부터 축복을 받으며 하루를 시작하고 있습니다. 또 파슈파티나트 사원과 바그마티 강변에 있는 아랴 갓은 화장장으로 이용되고 있습니다.",
