      "description": "에베레스트산은 높이가 해발 8,848.86 m로 지구에서 가장 높은 산입니다. 네팔에서는 사가르마타(산스크리트어: सगरमाथा)라 하고, 티베트어로는 초모랑마(티베트어: ཇོ་མོ་གླང་མ , 중국조선어: 쵸몰라마봉), 중국어와 문화어에서는 티베트어 '초모랑마'를 그대로 차용해 주무랑마봉이라고 부른다. '에베레스트'는 영국의 조지 에버리스트 경의 이름을 따서 붙여졌다. 에베레스트산은 가장 높은 산이지만, 지구의 중심에서 가장 멀리 떨어진 산은 아니다. 지구 중심에서 가장 먼 산은 안데스산맥의 침보라소산입니다. 중국과 네팔의 국경이 에베레스트산 정상을 지난다. 에베레스트산괴에는 주위의 로체산(8,516m), 눕체산(7,855m), 창체산(7,580m)이 포함된다.",
