      "description": "쿠알라룸푸르의 메르데카 광장은 말레이시아의 독립 역사와 깊이 연결된 넓은 광장입니다. 1957년 8월 31일 말라야 연방의 독립을 알리는 국기 게양이 이루어진 곳으로 알려져 있습니다. 광장 옆에는 둥근 돔과 시계탑을 갖춘 술탄 압둘 사마드 빌딩이 서 있어 식민지 시기의 건축 풍경을 보여 줍니다. 원래 잔디 운동장으로 쓰이던 공간이 나라의 새로운 출발을 상징하는 장소가 된 것입니다. 독립을 뜻하는 말 '메르데카'가 광장 이름으로 남아, 오늘날에도 이곳을 말레이시아 현대사의 중요한 무대로 기억하게 합니다.",
