      "description": "쿠알라룸푸르 타워(말레이어: Menara Kuala Lumpur; 자위: منارا کوالا لومڤور‎), 통칭 KL 타워는 말레이시아 쿠알라룸푸르에 있는 6층, 421-미터-tall (1,381-피트) 높이의 방송탑입니다. 안테나를 포함하여 높이가 421 미터 (1,381 ft)입니다. 포드(pod)의 지붕은 335 미터 (1,099 ft)에 있습니다. 탑의 나머지 부분은 계단과 엘리베이터를 통해 상부 지역으로 연결되며, 이곳에는 도시의 탁 트인 전망을 제공하는 회전 레스토랑도 있습니다. 참가자들이 계단을 통해 정상까지 오르는 경주가 매년 개최된다. 이 탑은 또한 라마단, 샤우왈, 두 알히자의 이슬람력의 시작을 알리는 초승달을 관측하는 이슬람 팔락 관측소 역할을 하며, 라마단, 하리 라야 아이딜피트리 및 이둘 아드하를 기념합니다.",
