      "description": "켁록시는 말레이시아 페낭주 조지타운에 있는 절입니다. 아예르이탐에 위치한 이 절은 말레이시아에서 가장 큰 절이며 홍콩, 필리핀, 싱가포르와 같은 동남아시아의 다른 지역에서 온 불교도들의 중요한 순례지다. 사원 단지 전체는 1890년에서 1930년 사이에 지어졌으며, 이는 수도원장인 베오 레안의 계획이었다. 이 단지의 주요 특징은 태국의 라마 6세 국왕이 의뢰한 7층짜리 만불탑으로, 10,000개의 설화석고와 청동 부처상, 자비의 여신인 관음 청동상이 특징입니다. 10,000개의 부처라는 개념은 중국 대승불교에 속하지만, 라마 6세는 테라바다와 불교 전통의 왕이었다. 대승불교, 상좌부불교, 중국의 전통의식은 사원 ​​건축과 예술 작품, 그리고 신도들의 일상 활동 모두에서 조화로운 전체로 융합되어 있습니다.",
