      "aliases": [],
      "description": "앙코르 톰(អង្គរធំ, Angkor Thom)은 옛 캄보디아 씨엠립에 있는 크메르 제국의 마지막 수도 유물군입니다. 12세기 후반에 자야바르만 7세에 의해 건립되었습니다. 캄보디아 톤레사프호(湖) 북방에 있는 앙코르문화의 유적입니다. 앙코르는 왕도(王都)를 톰은 큰(大)이라는 뜻을 나타내므로 앙코르톰은 '대왕도'라는 뜻입니다. 현존하는 유구(遺構)는 자야바르만 7세가 왕국의 수도로서 1200년경에 조영(造營)한 것입니다. 1변 3km인 성벽의 정사각형으로 주위를 둘러싸고, 중앙에는 세계의 중심으로 보이게 한 바이온묘(廟)가 높이 솟고, 그 동서남북으로 2추축대로(樞軸大路)가 도시를 4분하며 2추축이 성벽과 만나는 곳에 왕도의 문이 4개, 왕궁에서 동으로 뻗은 대로 위에 1개, 모두 5개의 문이 있습니다.",
