      "description": "인트라무로스(Intramuros)는 16세기에 스페인인들에 의해 지어진 필리핀의 수도 마닐라에서 가장 오래된 지역으로, 파시그 강 남쪽에 위치합니다. 그 명칭은 직역하면 스페인어로 \"벽 안에서\"가 되며, 벽에 둘러싸인 도시 또는 요새를 의미하고, 또한 그 두껍고 높은 벽과 해자로 둘러싸인 구조를 표현한 것입니다. 스페인 시대에는 인트라무로스가 마닐라 자체라고 생각되었습니다. 지금은 마닐라 입국관리국이 소재하고 있어 출입국 관련 업무를 보려는 외국인들이 많이 들르는 곳입니다.",
