      "description": "코론섬(Coron Island)은 필리핀 팔라완주 북부의 칼라미안 제도에서 세 번째로 큰 섬입니다. 이 섬은 같은 이름의 더 큰 자치체인 코론의 일부입니다. 마닐라에서 남서쪽으로 약 170 해리 (310 km) 떨어져 있으며, 태평양 전쟁 당시의 일본 제국 난파선들로 유명하다. 독특한 생태적 특징으로 인해 전체 지역이 여러 법령에 의해 보호받고 있습니다. 이 섬과 주변 어장은 원주민인 타그반와족의 조상 대대로의 영토에 속하며, 1998년 6월 5일 공식적으로 지정되었습니다. 이 섬은 타그반와족과 코론 주민들에게 '칼리스(Calis)'라고 불리며, 부족장은 로드돌포 아길라르 1세입니다. 이 섬은 코론 자치체 내의 두 바랑가이인 바누앙 다안(Banuang Daan)과 카부가오(Cabugao)로 구성되어 있습니다.",
