      "description": "간단 사원(몽골어: Гандантэгчинлэн хийд)은 몽골의 수도인 울란바타르에 위치하고 있는 사원입니다. 정식 이름은 간단테그치늘렌 사원이며, 한자로는 감단사(甘丹寺)로, 완벽한 기쁨의 위대한 장소라는 의미를 가진다. 간단테그치늘렌 사원은 19세기 중엽에 건축되었고 현재 몽골에서 가장 큰 사원이며 과거 공산정권하에서 유일하게 종교활동을 보장 받았던 매력적인 사원입니다. 중앙아시아에서 가장 큰 불상과 여러 개의 자은 절, 승려들의 기숙사, 부설 불교대학이 있습니다. 이 사원 건축은 처음 1838년에 제4대 보그드 게겐에 의하여 시작되었으며, 제5대 출템 지그미드 담비잔찬에 의해서 완성되었습니다. 대부분의 몽골 사원과 마찬가지로 간단사도 1937년에 큰 피해를 입었다.",
