      "aliases": [],
      "description": "카라코룸(몽골어: ᠬᠠᠷᠠᠬᠣᠷᠣᠮ, Хархорум)은 13세기에 약 30년간 몽골 제국의 수도였습니다. 그 유적이 몽골의 으브르항가이 주에 남아있으며, 근처에 카호린이라는 마을이 있습니다. 세계 유산 중의 하나인 오르혼 계곡 문화 지구의 위쪽을 차지하고 있습니다. 고고학적 유물 발견으로 오르혼강의 흐르는 물을 이용한 금속제련의 중심지였다는 것이 밝혀졌다. 카라코룸은 고대 초원의 제국의 중심지라고 불리는데, 이르면 8세기부터 이곳에 유목민들이 살았었던 것으로 밝혀졌다. 칭기즈 칸은 1220년 경에 이 지역에 머물렀으며 중국 원정을 위한 본거지로 삼아 몽골 제국의 시작을 열었다. 칭기즈 칸의 주요 경쟁자였던 나이만 몽골족의 수도였던 오늘날 울란바타르의 서쪽에 있는 카라코룸을 그의 새로운 제국의 본거지로 삼았다.",
