      "extraCategories": [],
      "region": "",
      "aliases": [],
      "description": "피라미드(pyramid)는 일반적으로 정사각뿔 꼴의 고대 유적을 가리킨다. 피라미드의 어원은 고대 그리스어 피라미스인데, 이집트인은 “pr-m-ws”라고 불렀다. 고대 중국, 이집트, 메소포타미아, 중앙아메리카 등 많은 문명권에서 피라미드 형태의 유적을 만들었다. 그중에서 고대 이집트의 피라미드, 특히 기자의 3대 피라미드가 가장 유명하다. 한때 이집트의 피라미드가 무덤이 아니라는 설도 있었으나, 대체로 국왕, 왕비 등 왕족의 무덤으로 쓰였을 것이라는 설이 가장 유력하다. 왕의 피라미드에서 미라가 여럿 발굴되었을 뿐 아니라 미라가 안치되었던 방에서 매장에 필요한 석관, 항아리, 황금 제품 등이 출토되었고, 부조나 비문 등에서 제사에 쓰였던 글이 발견되었기 때문입니다. 수단에도 피라미드가 존재하는데 현재의 수단 북부인 누비아 지방을 근거지로 삼았던 쿠시 왕국 시절에 이집트의 영향을 받아 지은 것으로 왕족들은 메로에 지역 피라미드에 다수 묻었다.",
