      "description": "살라딘, 또는 살라흐 앗딘 유수프 이븐 아이유브(아랍어: صلاح الدين الأيوبي, 쿠르드어: سەڵاحەددینی ئەییووبی, 페르시아어: صلاح الدین ایوبی, 튀르키예어: Selahaddin Eyyubi, 1138년?~1193년 3월 4일)은 12세기경 티크리트(현재 이라크 북부) 출신의 쿠르드족 무슬림 장군이자 전사였으며 이집트, 시리아의 술탄이었다. 3차 십자군 원정에 맞서서 이슬람 세력을 승리로 이끌었다. 전성기에 그는 이집트, 시리아, 예멘, 이라크, 메카, 헤자즈 등지를 아우르는 아이유브 왕조를 세웠다. 서양에서는 살라딘이라는 이름으로 유명하지만 그의 본명은 유수프(Yousuf)였습니다. 그는 그의 지도력과 군사적 역량으로 무슬림과 기독교계 모두에게 알려졌으며, 십자군과 맞서 전쟁을 치를 당시에 탐욕스럽고 무자비했던 십자군의 군주들에 비해 온건하고 약속을 잘 지키는 자비로운 군주로 덕망이 높았으며 그가 보인 기사도 정신과 자비심은 서방세계에 널리 전해져 수많은 전설과 기록으로 남았다.",
