      "aliases": [],
      "description": "왕가의 계곡은 이집트 룩소르 인근에 위치한 고대 이집트의 무덤 유적지로, 이집트 제18왕조부터 제20왕조까지 약 500년에 달하는 기간 동안 이집트 신왕국 시대의 파라오와 귀족들이 묻힌 곳입니다. 왕가의 계곡 자체는 고대도시 테베로부터 나일강 건너 서안에 위치한 와디 지형을 기반으로 암반을 깎아 조성한 곳이며, 이곳을 중심으로 테베 네크로폴리스가 형성되었습니다. 크게 두가지 구역으로 나뉘는데 하나는 대다수 왕릉이 늘어서 있는 동쪽 계곡, 다른 하나는 원숭이 계곡이라는 별칭이 있는 서쪽 계곡입니다. 왕가의 계곡은 신왕국 시대 주요 왕족과 여러 귀족층의 핵심적인 매장지로 기능하였습니다. 왕가의 계곡에 있는 무덤의 수는, 가장 최근인 2005년에 발견된 새로운 석실 한 곳과 2008년 발견된 무덤 입구 두 곳을 더하면, 총 65개의 무덤과 석실이 있는 것으로 파악되고 있습니다.",
