      "aliases": [],
      "description": "아마존강(스페인어: Río Amazonas, 브라질 포르투갈어: Rio Amazonas, 문화어: 아마조나스 강)은 남아메리카에 있는 강으로, 유수량으로는 세계에서 가장 큰 강이며, 나일강과 길이가 가장 길거나 두 번째로 긴 강을 두고 다투는 세계에서 가장 길거나 두 번째로 긴 강 체계입니다. 네바도 미스미에 있는 아푸리마크강의 발원지는 거의 한 세기 동안 아마존 분지의 가장 먼 발원지로 여겨져 왔으나, 2014년 연구에서 페루의 코르디예라 루미 크루스에 있는 만타로강의 발원지가 가장 먼 발원지임을 밝혀냈다. 만타로강과 아푸리마크강은 합류하여 다른 지류들과 함께 우카얄리강을 형성하고, 우카얄리강은 다시 페루 이키토스 상류에서 마라뇬강과 만나 브라질 외의 국가들이 아마존강의 본류라고 여기는 부분을 형성합니다.",
