      "description": "아일랜드의 뉴그레인지는 피라미드보다도 오래된 선사시대 거대한 무덤 유적입니다. 둥근 흙더미처럼 보이는 외관 속에는 돌로 만든 긴 통로와 방이 숨겨져 있습니다. 특히 신기한 점은 겨울 동지 무렵 떠오르는 태양빛이 입구 위의 좁은 틈으로 들어와 안쪽 통로를 비춘다는 사실입니다. 수천 년 전 사람들이 해가 떠오르는 방향과 계절의 변화를 세심하게 관찰했음을 보여 줍니다. 돌 표면에는 나선무늬 같은 문양이 새겨져 있어 당시 사람들이 어떤 생각과 믿음을 가졌는지 상상하게 합니다. 그 뜻을 모두 알아낸 것은 아니지만, 뉴그레인지는 옛사람들이 자연의 시간과 삶의 의식을 연결하려 했던 특별한 흔적입니다.",
