      "description": "아일랜드 남서쪽 바다의 스켈리그 마이클은 가파른 바위섬 위에 오래된 수도원 유적이 남아 있는 곳입니다. 수도자들은 거친 바닷바람을 맞는 좁은 공간에 돌을 쌓아 작은 집과 예배 장소를 만들었습니다.\n\n섬의 가파른 돌계단은 높은 바위벽을 따라 이어지고, 아래로는 끝없는 대서양이 펼쳐집니다. 사람이 머물기 어려운 환경 속에서 신앙생활을 이어갔던 흔적이 오늘날까지 남아 있어 특별한 역사유산으로 여겨집니다.",
