      "description": "탄자니아의 킬리만자로산은 해발 약 5,895미터로 아프리카에서 가장 높은 산입니다. 넓은 동아프리카 평원 위에 홀로 솟은 듯한 거대한 모습은 여러 산봉우리가 모인 산맥과는 다른 인상을 줍니다. 킬리만자로는 키보, 마웬지, 시라라는 화산체로 이루어져 있으며, 가장 높은 봉우리는 키보의 우후루 피크입니다. 산 아래쪽의 숲에서 시작해 고도가 높아질수록 초원과 고산 사막을 지나 차가운 정상부로 이어집니다. 적도 가까이에 있지만 정상 주변에는 오랫동안 얼음과 빙하가 남아 있었으며, 최근에는 빙하가 크게 줄어들어 기후변화의 상징적인 장소로도 주목받고 있습니다. 킬리만자로 국립공원은 유네스코 세계자연유산입니다.",
