      "description": "미얀마의 바간 평원에는 벽돌로 세운 불교 사원과 탑들이 넓은 대지 곳곳에 남아 있습니다. 11세기부터 13세기 사이 바간 왕국이 번성하면서 왕과 귀족, 주민들이 불교 신앙을 표현하기 위해 수많은 건축물을 세웠습니다. 어떤 사원은 높은 탑이 하늘로 솟고, 어떤 사원은 내부에 불상과 벽화를 간직하고 있습니다. 비슷해 보이는 탑들도 자세히 보면 문과 창의 모양, 불상을 모신 방식, 건축 시대가 다릅니다. 바간은 왕국의 정치와 종교가 어떻게 연결되어 있었는지 보여 주는 중요한 유적입니다. 여러 차례의 지진과 복구 작업을 거쳤으며, 2019년 유네스코 세계유산으로 등재되었습니다. 넓은 평원의 수많은 탑은 오래전 이곳이 번화한 왕국의 중심이었다는 사실을 지금도 전하고 있습니다.",
