      "description": "서태평양 북마리아나제도의 사이판은 맑은 바다와 산호초, 푸른 산이 있는 섬입니다. 마나가하섬 주변에는 밝은 모래와 청록빛 바다가 펼쳐지고, 사이판 본섬의 해안에는 바위와 절벽이 길게 이어집니다.\n\n사이판에는 제2차 세계대전의 흔적도 남아 있습니다. 오늘날 평화로운 바다 풍경 뒤에는 여러 사람들이 겪었던 무거운 역사가 함께 자리하고 있습니다. 이 작은 섬은 아름다운 열대 자연과 평화를 기억하는 이야기를 모두 품고 있습니다.",
