      "wikiLang": "en",
      "description": "볼리비아 안데스고원에 펼쳐진 우유니 소금사막은 끝이 보이지 않을 만큼 넓고 하얀 소금 평원입니다. 오래전 이 지역을 덮었던 거대한 호수들이 변하면서 물은 사라지고 두꺼운 소금층이 남았습니다. 평소에는 바닥에 육각형에 가까운 소금 무늬가 끝없이 이어져 다른 행성처럼 보이기도 합니다. 비가 내려 얕은 물이 고이면 풍경은 전혀 달라집니다. 물 위에 하늘과 구름이 비쳐 땅과 하늘의 경계가 사라진 듯한 거대한 거울이 되기 때문입니다. 하지만 비가 많이 내린다고 언제나 거울 풍경을 만날 수 있는 것은 아니며, 물의 깊이와 바람에 따라 모습이 달라집니다. 우유니는 소금뿐 아니라 리튬을 품은 지역으로도 주목받고 있습니다. 하얀 땅과 푸른 하늘이 만나는 이곳은 오랜 지질 변화와 계절의 힘이 빚어낸 독특한 자연경관입니다.",
