      "wikiTitle": "Victoria Falls",
      "wikiLang": "en",
      "description": "아프리카 남부의 잠베지강이 잠비아와 짐바브웨의 국경을 흐르다가 거대한 절벽 아래로 쏟아지는 곳이 빅토리아 폭포입니다. 폭포의 너비는 약 1.7킬로미터에 이르며, 떨어진 물은 좁고 깊은 현무암 협곡으로 몰려갑니다. 물소리와 함께 피어오른 물안개는 멀리에서도 보일 만큼 웅장합니다. 이 지역에서 사용되는 이름인 ‘모시 오아 툰야’는 흔히 ‘천둥 치는 연기’라는 뜻으로 풀이되는데, 폭포에서 솟는 하얀 물보라를 잘 나타냅니다. 잠베지강의 수량이 크게 달라져 물이 풍부한 시기에는 물안개가 폭포 전체를 뒤덮고, 물이 적은 시기에는 깎아지른 바위와 여러 갈래의 물줄기가 더 뚜렷해집니다. 수많은 세월 동안 강물이 바위를 깎으며 폭포의 위치와 협곡의 모양도 바뀌었습니다. 그 뛰어난 자연경관과 지질학적 가치를 인정받아 1989년 유네스코 세계자연유산에 올랐습니다.",
